/**
 * Arlo UI — Chart
 *
 * A single-series line/area chart you scrub with your finger, for the "how is this
 * number doing" screen: a portfolio, a balance, a metric over time.
 *
 *   <Chart data={points} periods={['1D','1W','1M','1Y','ALL']} period={p} onPeriodChange={setP} />
 *
 * That is the whole call. With no children the chart renders its documented
 * composition — value, delta, plot, periods, in that order. Name the parts when
 * you need to reorder or drop one:
 *
 *   <Chart data={points} format={formatMoney('USD')}>
 *     <Chart.Plot height={180} />
 *     <Chart.Value />
 *     <Chart.Periods />
 *   </Chart>
 *
 * The other five forms hang off the same namespace, each a complete chart rather
 * than a part of the one above:
 *
 *   <Chart.Sparkline data={points} />        inline line, no chrome
 *   <Chart.Bar data={bars} />                categorical bars
 *   <Chart.Donut data={slices} />            part-to-whole, legend required
 *   <Chart.Meter value={n} max={m} />        one value against a target
 *   <Chart.Heatmap data={days} />            calendar grid, no library needed
 *
 * Deliberate choices:
 *
 * - **No axis furniture.** No ticks, no gridlines, no axis labels — `chrome` has
 *   no `axis` member and will not get one. The value readout is the label, and it
 *   updates as you scrub. A chart at this size answers "shape and direction", not
 *   "what exactly was Tuesday".
 * - **Direction, not identity.** One series, so no legend and no categorical
 *   palette — the tone is `chartPositive` / `chartNegative`, chosen by whether the
 *   series ended above or below the `baseline`. The exceptions are explicit: a
 *   `compare` line and a `range` band are drawn in the neutral and the brand hue
 *   respectively, and `Chart.Legend` names them.
 * - **Direction is never colour-alone.** `Chart.Delta` always renders a sign,
 *   because the two tones sit near the deuteranopia separation floor.
 * - **Straight segments by default.** A spline through sparse points invents peaks
 *   and troughs that were never in the data, so `Chart.Plot` joins points with
 *   straight lines unless you ask for `curve="smooth"`.
 *
 * Arlo draws all of this itself, on `react-native-svg`. The geometry lives in
 * `core.ts` and there is exactly one scale, which is what puts the crosshair on
 * the line rather than near it.
 */
import {
  Children,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import {
  Animated,
  Easing,
  PanResponder,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from 'react-native-svg';
import { rgbaFromHex } from '@arloui/tokens';
import { AnimatedCounter } from '../animated-counter/animated-counter';
import { haptic } from '../../foundation/haptics';
import { useTokens } from '../../foundation/theme-provider';
import {
  areaPath,
  bandPath,
  densityMetrics,
  interpolateSeries,
  linePath,
  makeScale,
  resample,
  seriesColorAt,
  seriesStats,
  toPoints,
  toneColor,
  valuesOf,
  type ChartChrome,
  type ChartCurve,
  type ChartData,
  type ChartDensity,
  type ChartPoint,
  type ChartReference,
  type ChartTone,
} from './core';
import { EmptyContent, type ChartEmptyProps } from './empty';
import { SkeletonBlock } from './skeleton';

export type { ChartEmptyProps };
import { useControllableIndex, useReduceMotion, useSkeletonPulse } from './hooks';
import { BarChart } from './bar-chart';
import { DonutChart } from './donut-chart';
import { Meter } from './meter';
import { Sparkline } from './sparkline';
import { Heatmap } from './heatmap';
import { ChartLegend } from './legend';

export type { ChartCurve, ChartTone, ChartDensity, ChartChrome, ChartPoint, ChartData };

type ChartContextValue = {
  points: ChartPoint[];
  values: number[];
  /** Index under the finger, or `null` when nothing is being scrubbed. */
  activeIndex: number | null;
  setActiveIndex: (index: number | null) => void;
  /** The point the readout should show: the scrubbed one, else the last. */
  displayIndex: number;
  color: string;
  baseline: number;
  first: number;
  last: number;
  min: number;
  max: number;
  span: number;
  density: ChartDensity;
  chrome: ChartChrome;
  reference?: ChartReference | readonly ChartReference[];
  format?: (value: number) => string;
  formatAt?: (at: ChartPoint['at'], point: ChartPoint) => string;
  loading: boolean;
  empty?: ReactNode;
  periods: string[];
  period?: string;
  onPeriodChange?: (period: string) => void;
};

const ChartContext = createContext<ChartContextValue | null>(null);

function useChart(): ChartContextValue {
  const ctx = useContext(ChartContext);
  if (!ctx) throw new Error('Chart.* must be rendered inside <Chart>');
  return ctx;
}

export type ChartProps = {
  /** The series, oldest first. Bare numbers, or points carrying a time and a label. */
  data: ChartData;
  /**
   * Omit for the documented composition: value, delta, plot, periods. Name the
   * parts when you need a different order, or only some of them.
   */
  children?: ReactNode;
  /**
   * `'auto'` tones by whether the series ended above or below `baseline`. Force it
   * when the series' own direction isn't the story — e.g. spending, where "up" is
   * bad. A line has no categories, so `'series'` is treated as `'brand'`.
   */
  tone?: ChartTone;
  /** Reference value for tone and for the dashed baseline. Defaults to the first point. */
  baseline?: number;
  /** Stroke, dot, and label weight. `'compact'` drops labels for inline use. */
  density?: ChartDensity;
  /** Plot furniture. There is no `axis` member. */
  chrome?: ChartChrome;
  /**
   * The labelled line(s) drawn when `chrome="reference"` — one line, or several
   * for the min/max pair a dense series reads against. Not a band system.
   */
  reference?: ChartReference | readonly ChartReference[];
  /** Formats every value in the subtree — readout, delta, reference label. */
  format?: (value: number) => string;
  /** Formats a point's `at` for `Chart.Value`, so the readout can say *when*. */
  formatAt?: (at: ChartPoint['at'], point: ChartPoint) => string;
  periods?: string[];
  period?: string;
  onPeriodChange?: (period: string) => void;
  /** Controlled scrub position. Leave undefined to let the chart hold it. */
  activeIndex?: number | null;
  defaultActiveIndex?: number | null;
  /** Fires on every scrub change, controlled or not. `null` on release. */
  onScrub?: (index: number | null, point: ChartPoint | null) => void;
  /** Renders the plot's silhouette as a shimmer instead of the series. */
  loading?: boolean;
  style?: StyleProp<ViewStyle>;
};

/**
 * The documented default. Written out rather than generated so the order is
 * something you can read, and so `<Chart data periods />` and the spelled-out
 * form are provably the same chart.
 */
function defaultComposition() {
  return (
    <>
      <ChartValue />
      <ChartDelta />
      <ChartPlot />
      <ChartPeriods />
    </>
  );
}

function ChartRoot({
  data,
  children,
  tone = 'auto',
  baseline: baselineProp,
  density = 'default',
  chrome = 'baseline',
  reference,
  format,
  formatAt,
  periods = [],
  period,
  onPeriodChange,
  activeIndex: activeIndexProp,
  defaultActiveIndex = null,
  onScrub,
  loading = false,
  style,
}: ChartProps) {
  const t = useTokens();
  const [activeIndex, setInternalActive] = useControllableIndex(activeIndexProp, defaultActiveIndex);

  const points = useMemo(() => toPoints(data), [data]);
  const values = useMemo(() => valuesOf(points), [points]);
  const stats = useMemo(() => seriesStats(points), [points]);

  const baseline = baselineProp ?? stats.first;
  const color = toneColor(t, tone, { rising: stats.last >= baseline });
  const displayIndex = activeIndex ?? Math.max(0, points.length - 1);

  const setActiveIndex = useCallback(
    (index: number | null) => {
      setInternalActive(index);
      onScrub?.(index, index == null ? null : (points[index] ?? null));
    },
    [setInternalActive, onScrub, points],
  );

  /*
   * `Chart.Empty` is configuration, not output: it contributes what the plot
   * should draw when there is no series, and renders nothing itself. Pulling it
   * out of the children here keeps it declarative without needing an effect to
   * register it, and without the plot and the slot both painting a message.
   */
  const { empty, rest } = useMemo(() => {
    if (children == null) return { empty: undefined, rest: null };
    let slot: ReactNode;
    const kept: ReactNode[] = [];
    Children.forEach(children, (child) => {
      if (isValidElement(child) && child.type === ChartEmpty) {
        const props = (child as ReactElement<ChartEmptyProps>).props;
        // `children` is the escape hatch and wins outright; otherwise the slot
        // is the standard headline / line / action arrangement.
        slot =
          props.children ??
          (props.title || props.description || props.action ? (
            <EmptyContent {...props} />
          ) : undefined);
        return;
      }
      kept.push(child);
    });
    return { empty: slot, rest: kept };
  }, [children]);

  const ctx = useMemo<ChartContextValue>(
    () => ({
      points,
      values,
      activeIndex,
      setActiveIndex,
      displayIndex,
      color,
      baseline,
      density,
      chrome,
      reference,
      format,
      formatAt,
      loading,
      empty,
      periods,
      period,
      onPeriodChange,
      ...stats,
    }),
    [
      points,
      values,
      activeIndex,
      setActiveIndex,
      displayIndex,
      color,
      baseline,
      density,
      chrome,
      reference,
      format,
      formatAt,
      loading,
      empty,
      periods,
      period,
      onPeriodChange,
      stats,
    ],
  );

  return (
    <ChartContext.Provider value={ctx}>
      <View style={[{ gap: t.spacing[2] }, style]}>{children == null ? defaultComposition() : rest}</View>
    </ChartContext.Provider>
  );
}

/**
 * What the plot draws when the series is empty. Renders nothing where you put it —
 * the plot picks the content up and draws it in its own box, so the chart keeps
 * its height and the layout doesn't jump when data arrives.
 *
 * Failing to a blank rectangle is how a data screen looks broken, so the default
 * arrangement is a headline, one line, and one action:
 *
 *   <Chart data={[]}>
 *     <Chart.Empty
 *       title="No activity yet"
 *       description="Your spending will show up here once you make your first transaction."
 *       action={{ label: 'Log a transaction', onPress: open }}
 *     />
 *     <Chart.Plot />
 *   </Chart>
 *
 * `children` still takes anything, and a bare string still works — the slot was
 * a string before it had this shape and consumers should not have to migrate for
 * a default they were already happy with.
 */
function ChartEmpty(_: ChartEmptyProps): ReactNode {
  return null;
}

/** The headline number. Rolls between values as you scrub. */
function ChartValue({
  format: formatProp,
  /** Show the active point's `at` under the number. Needs `formatAt` on the root. */
  showAt = true,
  style,
}: {
  format?: (value: number) => string;
  showAt?: boolean;
  /** Wraps the counter, so this is a view style — the type ramp comes from tokens. */
  style?: StyleProp<ViewStyle>;
}) {
  const t = useTokens();
  const { points, displayIndex, format: contextFormat, formatAt, loading } = useChart();
  const format = formatProp ?? contextFormat;
  const point = points[displayIndex];
  const value = point?.value ?? 0;
  const text = format ? format(value) : String(value);

  // The "when" line: whatever `formatAt` makes of the point's timestamp, else the
  // point's own label. Only rendered if one of them actually says something.
  const caption =
    showAt && point ? (formatAt ? formatAt(point.at, point) : point.label) : undefined;

  if (loading) {
    return (
      <View style={[{ alignItems: 'flex-start', gap: 6 }, style]}>
        <SkeletonBlock width={150} height={26} radius={7} />
      </View>
    );
  }

  return (
    <View style={[{ alignItems: 'flex-start' }, style]}>
      <AnimatedCounter
        text={text}
        fontSize={t.typography.displayMedium.fontSize}
        lineHeight={t.typography.displayMedium.lineHeight}
        // Ink, not the series colour — the line already carries direction.
        color={t.colors.textPrimary}
        fontFamily={t.fontFamilies.sans}
        fontWeight="700"
      />
      {caption ? (
        <Text
          style={{
            color: t.colors.textSecondary,
            fontFamily: t.fontFamilies.sans,
            fontSize: t.typography.bodySm.fontSize,
            lineHeight: t.typography.bodySm.lineHeight,
          }}
        >
          {caption}
        </Text>
      ) : null}
    </View>
  );
}

/**
 * Change from the baseline to the shown point. Always renders an explicit sign —
 * that sign is what keeps direction readable when the two tones are hard to tell
 * apart, so don't strip it.
 */
function ChartDelta({
  format: formatProp,
  showPercent = true,
  style,
}: {
  format?: (value: number) => string;
  showPercent?: boolean;
  style?: StyleProp<TextStyle>;
}) {
  const t = useTokens();
  const { points, displayIndex, baseline, color, format: contextFormat, loading } = useChart();
  const format = formatProp ?? contextFormat;
  const value = points[displayIndex]?.value ?? 0;
  const change = value - baseline;
  const sign = change > 0 ? '+' : change < 0 ? '−' : '';
  const magnitude = Math.abs(change);
  const percent = baseline === 0 ? 0 : (change / Math.abs(baseline)) * 100;
  const formatted = format ? format(magnitude) : String(magnitude);

  // A signed delta is a claim about direction. There is nothing to claim yet.
  if (loading) return <SkeletonBlock width={96} height={13} radius={5} />;

  return (
    <Text
      style={[
        {
          color,
          fontFamily: t.fontFamilies.sans,
          fontSize: t.typography.body.fontSize,
          lineHeight: t.typography.body.lineHeight,
          fontWeight: '600',
        },
        style,
      ]}
    >
      {sign}
      {formatted}
      {showPercent ? ` (${sign}${Math.abs(percent).toFixed(2)}%)` : ''}
    </Text>
  );
}

/** The two bounds of the shaded band `Chart.Plot` draws for a `range`. */
export type ChartRange = { lower: ChartData; upper: ChartData };

export type ChartPlotProps = {
  height?: number;
  /** Fade a gradient under the line. */
  fill?: boolean;
  /** Turn off scrubbing for a static, decorative plot. */
  scrubbable?: boolean;
  /** Straight segments (default) or a fitted spline. See `ChartCurve`. */
  curve?: ChartCurve;
  /** Overrides the root's `chrome` for this plot. */
  chrome?: ChartChrome;
  /** One reference line, or several — the min/max pair a dense series reads against. */
  reference?: ChartReference | readonly ChartReference[];
  /**
   * A second series, drawn dashed in the neutral hue — the baseline a projection
   * is measured against. It never takes the scrub: one series answers to the
   * finger, the other is context.
   */
  compare?: ChartData;
  /**
   * A shaded band between two bounds — the "likely range" behind a projection.
   * A prop on Plot rather than a new form: the readout, the scrub, and the tone
   * all still belong to the primary series.
   */
  range?: ChartRange;
  /**
   * Series stacked on top of the primary — part-to-total over time, the shape a
   * bar chart draws with `variant="stacked"` when the x-axis is continuous
   * rather than categorical.
   *
   * Each entry is added to the running total, so the top edge of the last layer
   * is the sum of everything. They take the categorical palette and are drawn as
   * filled bands, not lines: a stack is read by the thickness of each layer, and
   * outlining every one turns it back into a set of overlapping lines.
   *
   * `stack` is distinct from `compare`, which is a *second* series measured
   * against the first rather than added to it — and from `range`, which is one
   * band around one series. Stacking implies the parts sum to something
   * meaningful; the other two do not.
   *
   * The primary still owns the scrub, the readout, and the tone. Negatives are
   * clamped to zero, matching the bar chart: a negative share of a total is not
   * a thing the shape can express.
   */
  stack?: readonly ChartData[];
  /**
   * Floating readout pill above the crosshair while scrubbing, showing the
   * formatted value of the point under the finger. The big `Chart.Value` stays
   * the primary readout — this is for dense series where the eye is on the plot,
   * not above it.
   */
  tooltip?: boolean;
  /** Shown when the series is empty. `Chart.Empty` wins over this. */
  emptyLabel?: string;
  /** Shown for a one-point series, which has no shape to draw. */
  notEnoughLabel?: string;
  /** Announced by screen readers in place of the visual plot. */
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

/** A generic rise-and-settle silhouette, drawn while `loading`. */
const SHIMMER_SHAPE = [0.35, 0.5, 0.42, 0.68, 0.55, 0.78, 0.7, 0.92];

function ChartPlot({
  height = 180,
  fill = true,
  scrubbable = true,
  curve = 'steep',
  chrome: chromeProp,
  reference: referenceProp,
  compare,
  stack,
  range,
  tooltip = false,
  emptyLabel = 'No data',
  notEnoughLabel = 'Not enough data',
  accessibilityLabel,
  style,
}: ChartPlotProps) {
  const t = useTokens();
  const {
    points,
    values,
    activeIndex,
    setActiveIndex,
    color,
    baseline,
    min,
    max,
    span,
    first,
    last,
    density,
    chrome: contextChrome,
    reference: contextReference,
    format,
    loading,
    empty,
  } = useChart();
  const chrome = chromeProp ?? contextChrome;
  const reference = referenceProp ?? contextReference;
  /*
   * `reference` accepts one line or the min/max pair. Normalising here keeps
   * every draw site a loop over a list rather than a branch per arity.
   */
  const references = useMemo(() => {
    if (reference == null) return [];
    return (Array.isArray(reference) ? reference : [reference]).filter(
      (entry) => typeof entry?.value === 'number',
    );
  }, [reference]);
  const metrics = densityMetrics(density);
  const inset = metrics.inset;

  const compareValues = useMemo(() => (compare ? valuesOf(toPoints(compare)) : []), [compare]);

  /**
   * The stack as cumulative top edges, outermost last.
   *
   * Each layer carries the running total rather than its own value, because that
   * is what gets drawn: a stacked area is a set of nested areas, and the band a
   * reader sees is the gap between one cumulative edge and the one below it.
   * Summing at draw time instead would recompute the same totals per frame.
   */
  const stackLayers = useMemo(() => {
    if (!stack || stack.length === 0) return [];
    const layers: number[][] = [];
    let running = values.slice();
    for (const entry of stack) {
      const next = valuesOf(toPoints(entry));
      running = running.map((total, index) => total + Math.max(0, next[index] ?? 0));
      layers.push(running);
    }
    return layers;
  }, [stack, values]);
  const upperValues = useMemo(() => (range ? valuesOf(toPoints(range.upper)) : []), [range]);
  const lowerValues = useMemo(() => (range ? valuesOf(toPoints(range.lower)) : []), [range]);

  const [width, setWidth] = useState(0);
  const reduceMotion = useReduceMotion();
  const count = points.length;

  const handleLayout = useCallback((event: LayoutChangeEvent) => {
    setWidth(event.nativeEvent.layout.width);
  }, []);

  /*
   * Period morph. Two periods are different *lengths*, so there is nothing to
   * tween between until both ends are resampled onto a common length — then it is
   * one number per point. What gets drawn mid-flight is the interpolated series;
   * what it lands on is always the real one, so no frame of this is data the
   * chart invented and kept.
   */
  const [morphValues, setMorphValues] = useState<number[] | null>(null);
  const previousValues = useRef<number[]>(values);
  // Lazy `useState`, not `useRef(new Animated.Value())`: the ref form allocates a
  // throwaway Value every render and reads `.current` during render, which is what
  // the refs lint rule exists to catch.
  const [progress] = useState(() => new Animated.Value(1));

  useEffect(() => {
    const from = previousValues.current;
    const to = values;
    previousValues.current = to;

    const unchanged = from.length === to.length && from.every((v, i) => v === to[i]);
    // A first paint has nothing to morph from, and a scrub in flight must not be
    // interrupted by the line moving under the finger.
    if (unchanged || from.length === 0 || to.length === 0 || reduceMotion) {
      setMorphValues(null);
      return;
    }

    const frames = Math.max(from.length, to.length);
    const a = resample(from, frames);
    const b = resample(to, frames);

    progress.setValue(0);
    const id = progress.addListener(({ value: p }) => setMorphValues(interpolateSeries(a, b, p)));
    const animation = Animated.timing(progress, {
      toValue: 1,
      duration: t.motion.chart.data.duration,
      easing: Easing.bezier(...t.motion.chart.data.easing),
      // Path `d` is a string built in JS — there is no native equivalent to drive.
      useNativeDriver: false,
    });
    animation.start(({ finished }) => {
      // Land on the real series, not on the last interpolated frame.
      if (finished) setMorphValues(null);
    });
    return () => {
      animation.stop();
      progress.removeListener(id);
      setMorphValues(null);
    };
  }, [values, progress, reduceMotion, t.motion.chart.data.duration, t.motion.chart.data.easing]);

  /*
   * Mid-morph the drawn series is the interpolated one, so the scale has to be
   * built from whatever is actually on screen — otherwise a series moving into a
   * new range would clip against the old one for the length of the tween.
   */
  const drawnValues = morphValues ?? values;

  /*
   * The scale has to fit everything that is drawn, not just the primary series —
   * a compare line or a band that pokes past the primary's extremes would clip.
   * The extras are static per layout, so the union is one scan.
   */
  const extrasRange = useMemo(() => {
    let lo = Number.POSITIVE_INFINITY;
    let hi = Number.NEGATIVE_INFINITY;
    for (const list of [compareValues, upperValues, lowerValues, ...stackLayers]) {
      for (const value of list) {
        if (value < lo) lo = value;
        if (value > hi) hi = value;
      }
    }
    return lo === Number.POSITIVE_INFINITY ? null : { min: lo, max: hi };
  }, [compareValues, upperValues, lowerValues, stackLayers]);

  const drawnRange = useMemo(() => {
    let lo = morphValues ? (morphValues[0] ?? 0) : min;
    let hi = morphValues ? lo : max;
    if (morphValues) {
      for (const value of morphValues) {
        if (value < lo) lo = value;
        if (value > hi) hi = value;
      }
    }
    if (extrasRange) {
      lo = Math.min(lo, extrasRange.min);
      hi = Math.max(hi, extrasRange.max);
    }
    return { min: lo, span: hi - lo };
  }, [morphValues, min, max, extrasRange]);

  const scale = useMemo(
    () =>
      makeScale({
        count: drawnValues.length,
        min: drawnRange.min,
        span: drawnRange.span,
        width,
        height,
        inset,
      }),
    [drawnValues.length, drawnRange.min, drawnRange.span, width, height, inset],
  );

  /*
   * The extras share the primary's domain but not its point count, so each is
   * placed by a scale of its own — a forecast band may sample monthly against a
   * daily primary line, and both still have to land on the same x track.
   */
  const extraScale = useCallback(
    (seriesCount: number) =>
      makeScale({
        count: seriesCount,
        min: drawnRange.min,
        span: drawnRange.span,
        width,
        height,
        inset,
      }),
    [drawnRange.min, drawnRange.span, width, height, inset],
  );

  const band = useMemo(() => {
    if (width === 0 || upperValues.length === 0 || lowerValues.length === 0) return '';
    const upper = extraScale(upperValues.length);
    const lower = extraScale(lowerValues.length);
    return bandPath(
      upperValues.map((value, index) => ({ x: upper.x(index), y: upper.y(value) })),
      lowerValues.map((value, index) => ({ x: lower.x(index), y: lower.y(value) })),
      curve,
    );
  }, [upperValues, lowerValues, width, extraScale, curve]);

  /*
   * The compare line and the band take the plot's `curve`, not a hardcoded one.
   *
   * This was pinned to `'steep'`, so `curve="smooth"` drew a fitted spline for the
   * primary over a hard-cornered comparison and a hard-cornered band — three
   * marks over the same x-range disagreeing about how the data is interpolated.
   * `curve` is one decision for the whole plot.
   */
  /**
   * Each layer as a closed band between its own top edge and the edge below it.
   *
   * Drawn outermost-first so the nearer layers paint over the farther ones — the
   * fills are opaque, so a stack drawn the other way would bury every band but
   * the last under the total.
   */
  const stackBands = useMemo(() => {
    if (width === 0 || stackLayers.length === 0) return [];
    const toPts = (list: readonly number[]) => {
      const s = extraScale(list.length);
      return list.map((value, index) => ({ x: s.x(index), y: s.y(value) }));
    };
    return stackLayers
      .map((layer, index) => ({
        d: bandPath(toPts(layer), toPts(stackLayers[index - 1] ?? values), curve),
        // Slot 0 belongs to the primary, which takes a palette slot too once it
        // is stacked — see `lineColor`.
        color: seriesColorAt(t, index + 1),
      }))
      .reverse();
  }, [stackLayers, values, width, extraScale, curve, t]);

  /*
   * Once a plot is stacked, the primary takes a palette slot and `tone` stops
   * applying — the same rule the bar chart uses for `series`, and for the same
   * reason: a stack is a set of categories, not one measurement with a
   * direction, so there is nothing for `positive`/`negative` to mean.
   *
   * It also has to be this way to stay legible. The layers came off the
   * categorical palette while the primary stayed on the tone palette, and those
   * two sets are not checked against each other: the default `auto` tone
   * resolves to `chartPositive` (#008236, green) and the first layer landed on
   * `chartSeries2` (#65A30D, olive) — two greens side by side in the same stack,
   * with a legend claiming they were different things.
   */
  const stacked = stackLayers.length > 0;
  const lineColor = stacked ? seriesColorAt(t, 0) : color;

  const comparePath = useMemo(() => {
    if (width === 0 || compareValues.length < 2) return '';
    const compare = extraScale(compareValues.length);
    return linePath(
      compareValues.map((value, index) => ({ x: compare.x(index), y: compare.y(value) })),
      curve,
    );
  }, [compareValues, width, extraScale, curve]);

  // The scale the *gesture* reads. Pinned to the real series so the index under
  // the finger never depends on how far through a morph the chart happens to be.
  const scrubScale = useMemo(
    () => makeScale({ count, min, span, width, height, inset }),
    [count, min, span, width, height, inset],
  );

  // One tick per point the scrub actually lands on. Keying off the committed
  // index rather than the touch stream is what collapses a drag's many move
  // events down to the handful of points it crossed — React drops the re-render
  // when the index doesn't change, so this effect doesn't run either.
  useEffect(() => {
    if (activeIndex == null) return;
    void haptic('selection');
  }, [activeIndex]);

  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => scrubbable,
        onMoveShouldSetPanResponder: () => scrubbable,
        // Claim the gesture so a parent ScrollView doesn't steal a horizontal drag.
        onPanResponderTerminationRequest: () => false,
        onPanResponderGrant: (event) =>
          setActiveIndex(scrubScale.indexAt(event.nativeEvent.locationX)),
        onPanResponderMove: (event) =>
          setActiveIndex(scrubScale.indexAt(event.nativeEvent.locationX)),
        onPanResponderRelease: () => setActiveIndex(null),
        onPanResponderTerminate: () => setActiveIndex(null),
      }),
    [scrubScale, setActiveIndex, scrubbable],
  );

  const plotPoints = useMemo(
    () => drawnValues.map((value, index) => ({ x: scale.x(index), y: scale.y(value) })),
    [drawnValues, scale],
  );

  const line = linePath(plotPoints, curve);
  const area = fill ? areaPath(plotPoints, height - inset, curve) : '';

  const baselineY = scale.y(baseline);
  const showBaseline =
    chrome === 'baseline' &&
    count > 1 &&
    baseline >= drawnRange.min &&
    baseline <= drawnRange.min + drawnRange.span &&
    drawnRange.span > 0;
  const showReferences = chrome === 'reference' && references.length > 0 && count > 1;

  const active = activeIndex != null && count > 1 && morphValues == null
    ? { x: scrubScale.x(activeIndex), y: scrubScale.y(values[activeIndex] ?? min) }
    : null;

  // Measured once so the pill can be kept inside the plot at the plot's edges.
  const [pillWidth, setPillWidth] = useState(0);
  const activeValue = activeIndex != null ? (values[activeIndex] ?? 0) : 0;
  const tooltipText = tooltip && active ? (format ? format(activeValue) : String(activeValue)) : null;
  const pillLeft =
    active && pillWidth > 0
      ? Math.min(
          Math.max(active.x, pillWidth / 2 + 2),
          Math.max(pillWidth / 2 + 2, width - pillWidth / 2 - 2),
        )
      : (active?.x ?? 0);

  // Per instance: two charts on one screen resolve to different colours but would
  // share one document-global gradient id, so the first definition would win.
  const gradientId = `arloChartFill-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;

  const summary =
    accessibilityLabel ??
    (loading
      ? 'Chart loading'
      : count === 0
        ? emptyLabel
        : count === 1
          ? notEnoughLabel
          : `Line chart, ${count} points, from ${first} to ${last}, low ${min}, high ${max}`);

  const message =
    count === 0 ? (empty ?? emptyLabel) : count === 1 ? notEnoughLabel : null;
  const drawable = !loading && count > 1 && width > 0;

  return (
    <View
      onLayout={handleLayout}
      accessible
      accessibilityRole="image"
      accessibilityLabel={summary}
      style={[{ height, width: '100%' }, style]}
      {...(scrubbable && drawable ? panResponder.panHandlers : {})}
    >
      {loading ? (
        <PlotShimmer width={width} height={height} inset={inset} />
      ) : null}

      {drawable ? (
        <Svg width={width} height={height} style={{ position: 'absolute' }} pointerEvents="none">
          {band ? (
            <Path
              d={band}
              fill={rgbaFromHex(t.colors.interactivePrimary, 0.12)}
              stroke="none"
            />
          ) : null}

          {/*
            Under the primary, which keeps the line that answers the scrub on top
            of everything it is stacked with.
          */}
          {stackBands.map((layer, index) => (
            <Path key={`stack-${index}`} d={layer.d} fill={layer.color} stroke="none" />
          ))}

          {area ? (
            <>
              <Defs>
                <LinearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                  <Stop offset="0" stopColor={lineColor} stopOpacity={0.22} />
                  <Stop offset="1" stopColor={lineColor} stopOpacity={0} />
                </LinearGradient>
              </Defs>
              <Path d={area} fill={`url(#${gradientId})`} />
            </>
          ) : null}

          {showBaseline ? (
            <Path
              d={`M${inset},${baselineY.toFixed(2)} L${(width - inset).toFixed(2)},${baselineY.toFixed(2)}`}
              stroke={t.colors.borderSecondary}
              strokeWidth={1}
              strokeDasharray="3 4"
              fill="none"
            />
          ) : null}

          {showReferences
            ? references.map((entry, index) => (
                <Path
                  key={`reference-${index}-${entry.value}`}
                  d={`M${inset},${scale.y(entry.value).toFixed(2)} L${(width - inset).toFixed(2)},${scale.y(entry.value).toFixed(2)}`}
                  stroke={t.colors.borderSecondary}
                  strokeWidth={1}
                  strokeDasharray="2 3"
                  fill="none"
                />
              ))
            : null}

          {comparePath ? (
            <Path
              d={comparePath}
              stroke={t.colors.chartOther}
              strokeWidth={metrics.stroke}
              strokeLinecap="round"
              strokeDasharray="4 4"
              fill="none"
            />
          ) : null}

          <Path
            d={line}
            stroke={lineColor}
            strokeWidth={metrics.stroke}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />

          {active ? (
            <>
              <Path
                d={`M${active.x.toFixed(2)},${inset} L${active.x.toFixed(2)},${(height - inset).toFixed(2)}`}
                stroke={t.colors.borderSecondary}
                strokeWidth={1}
                fill="none"
              />
              {/* Surface ring keeps the dot readable where it overlaps the line. */}
              <Circle
                cx={active.x}
                cy={active.y}
                r={metrics.dot}
                fill={lineColor}
                stroke={t.colors.surfaceElevated}
                strokeWidth={2}
              />
            </>
          ) : null}
        </Svg>
      ) : null}

      {/* Reference labels ride outside the SVG so they use the same type ramp as
          everything else, rather than SVG's own text metrics. */}
      {drawable &&
        showReferences &&
        references.map((entry, index) => (
          <View
            key={`reference-label-${index}-${entry.value}`}
            pointerEvents="none"
            style={{ position: 'absolute', right: inset, top: scale.y(entry.value) - metrics.labelSize - 4 }}
          >
            <Text
              style={{
                color: t.colors.textTertiary,
                fontFamily: t.fontFamilies.mono,
                fontSize: metrics.labelSize - 1,
                fontWeight: '500',
              }}
            >
              {entry.label ?? (format ? format(entry.value) : String(entry.value))}
            </Text>
          </View>
        ))}

      {/* The scrub readout: a pill above the crosshair, kept inside the plot once
          its width is known. Same ramp rule as the labels above — RN text, not
          SVG text. */}
      {drawable && tooltipText != null && active ? (
        <View
          pointerEvents="none"
          onLayout={(event) => setPillWidth(event.nativeEvent.layout.width)}
          style={{
            position: 'absolute',
            left: pillLeft,
            top: Math.max(0, active.y - metrics.dot - 28),
            transform: [{ translateX: '-50%' }],
            backgroundColor: t.colors.surfaceInverse,
            borderRadius: 6,
            paddingHorizontal: 9,
            paddingVertical: 4,
          }}
        >
          <Text
            style={{
              color: t.colors.textInverse,
              fontFamily: t.fontFamilies.sans,
              fontSize: 11,
              lineHeight: 14,
              fontWeight: '700',
            }}
          >
            {tooltipText}
          </Text>
        </View>
      ) : null}

      {!loading && message != null ? (
        <View
          /*
           * `box-none`, not `none`: an empty slot can carry an action, and
           * `none` made that button unpressable — the one control on a screen
           * with no data, dead. `box-none` keeps the overlay itself out of the
           * way of the plot while letting its children take a touch.
           */
          pointerEvents="box-none"
          // `absoluteFill`, not `absoluteFillObject`: RN 0.86 dropped the latter, and
          // it fails silently — the lookup is `undefined`, so the overlay defines no
          // geometry and collapses to zero size.
          style={[StyleSheet.absoluteFill, { alignItems: 'center', justifyContent: 'center' }]}
        >
          {typeof message === 'string' ? (
            <Text
              style={{
                color: t.colors.textTertiary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {message}
            </Text>
          ) : (
            message
          )}
        </View>
      ) : null}
    </View>
  );
}

/**
 * Loading is the plot's own silhouette, pulsing — not a grey rectangle. A block
 * where a chart goes tells you the layout; a line where the line goes tells you
 * what is arriving.
 */
function PlotShimmer({
  width,
  height,
  inset,
}: {
  width: number;
  height: number;
  inset: number;
}) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);

  if (width === 0) return null;

  const scale = makeScale({
    count: SHIMMER_SHAPE.length,
    min: 0,
    span: 1,
    width,
    height,
    inset,
  });
  const shape = SHIMMER_SHAPE.map((value, index) => ({ x: scale.x(index), y: scale.y(value) }));

  /*
   * A filled silhouette, not a stroked line.
   *
   * The skeleton has to hold the same visual weight the plot will, and a hairline
   * over an empty box reads as a drawn chart with no data rather than as one
   * still arriving. Filling the silhouette gives the loading state the mass of
   * the area it stands in for, so nothing re-weights when the series lands.
   */
  return (
    <Animated.View style={[StyleSheet.absoluteFill, { opacity: pulse }]}>
      <Svg width={width} height={height} pointerEvents="none">
        <Path d={areaPath(shape, height - inset, 'smooth')} fill={t.colors.surfaceStrong} />
      </Svg>
    </Animated.View>
  );
}

/** Time-range selector. Renders nothing when the chart was given no `periods`. */
function ChartPeriods({ style }: { style?: StyleProp<ViewStyle> }) {
  const t = useTokens();
  const { periods, period, onPeriodChange, color, loading } = useChart();
  if (periods.length === 0) return null;

  /*
   * Skeleton pills while loading, not a live selector.
   *
   * A pressable period row over a chart that has no series lets the reader ask
   * for 1Y and get the same shimmer back, so the control reads as broken. It
   * keeps the row's exact footprint so nothing reflows when the data lands.
   */
  if (loading) {
    return (
      <View
        // Not a tablist while there is nothing to select between.
        accessibilityRole="progressbar"
        accessibilityLabel="Loading"
        style={[{ flexDirection: 'row', alignItems: 'center', gap: 6 }, style]}
      >
        {periods.map((option) => (
          <View key={option} style={{ flex: 1 }}>
            <SkeletonBlock width="100%" height={26} radius={t.radii.md} />
          </View>
        ))}
      </View>
    );
  }

  return (
    <View
      accessibilityRole="tablist"
      style={[{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[1] }, style]}
    >
      {periods.map((option) => {
        const selected = option === period;
        return (
          <Pressable
            key={option}
            accessibilityRole="tab"
            accessibilityLabel={option}
            accessibilityState={{ selected }}
            onPress={() => {
              void haptic('selection');
              onPeriodChange?.(option);
            }}
            hitSlop={8}
            style={({ pressed }) => ({
              flex: 1,
              minHeight: 32,
              paddingHorizontal: t.spacing[2],
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: t.radii.md,
              backgroundColor: selected ? t.colors.surfaceInput : 'transparent',
              // The control answers instantly; the series it selects is what takes
              // `motion.chart.data` to morph.
              opacity: pressed ? t.motion.pressed.opacity : 1,
              cursor: Platform.OS === 'web' ? 'pointer' : undefined,
            })}
          >
            <Text
              style={{
                color: selected ? color : t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
                fontWeight: selected ? '700' : '500',
              }}
            >
              {option}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/**
 * `Value`/`Delta`/`Plot`/`Periods`/`Empty`/`Legend` compose the scrubbable chart
 * above; `Sparkline`, `Bar`, `Donut`, `Meter`, and `Heatmap` are whole charts in
 * their own right, namespaced here so picking a form is one decision at one
 * import rather than five names to remember. They stay in their own files —
 * import those directly if you only copied one form into your project.
 *
 * The forms Arlo does **not** ship, and will not: candlestick, radar, population
 * pyramid, scatter, and 3-D anything. They are consumer-owned. `core.ts` exports
 * the scale and the path builders, so writing one against the same geometry is a
 * supported thing to do — it is just not in the kit.
 */
export const Chart = Object.assign(ChartRoot, {
  Value: ChartValue,
  Delta: ChartDelta,
  Plot: ChartPlot,
  Periods: ChartPeriods,
  Empty: ChartEmpty,
  Legend: ChartLegend,
  Sparkline,
  Bar: BarChart,
  Donut: DonutChart,
  Meter,
  Heatmap,
});

/**
 * Arlo UI — Chart core
 *
 * The shared vocabulary and the geometry, in one place and with no rendering in
 * it. Every form in the folder measures its data through these functions, which
 * is what makes the crosshair land on the line: there is one scale, not one per
 * component agreeing with a library's by coincidence.
 *
 * Nothing here imports React Native or a charting library. It is arithmetic and
 * path strings, so it is testable on its own and portable to whatever draws.
 */
import type { useTokens } from '../../foundation/theme-provider';

type Tokens = ReturnType<typeof useTokens>;

/* ------------------------------------------------------------------ data --- */

/**
 * A point in a series. `value` is all that is required; the rest is what lets a
 * readout say *when* as well as *what*.
 *
 * `at` is deliberately loose — a timestamp, an ISO string, or a `Date`. Charts
 * never parse it; they hand it back to your `formatAt` so the chart does not
 * acquire an opinion about time zones.
 */
export type ChartPoint = {
  value: number;
  at?: number | string | Date;
  label?: string;
  /** Anything you need back in a selection callback. Never read by the chart. */
  meta?: unknown;
};

/** A bare `number[]` is sugar for points with no label and no time. */
export type ChartData = readonly number[] | readonly ChartPoint[];

export function toPoints(data: ChartData): ChartPoint[] {
  return (data as ReadonlyArray<number | ChartPoint>).map((entry) =>
    typeof entry === 'number' ? { value: entry } : entry,
  );
}

export function valuesOf(points: readonly ChartPoint[]): number[] {
  return points.map((point) => point.value);
}

export type SeriesStats = {
  count: number;
  first: number;
  last: number;
  min: number;
  max: number;
  /** `max - min`. Zero for a flat series, which every scale has to survive. */
  span: number;
};

export function seriesStats(points: readonly ChartPoint[]): SeriesStats {
  const head = points[0];
  if (head == null) return { count: 0, first: 0, last: 0, min: 0, max: 0, span: 0 };
  let min = head.value;
  let max = head.value;
  for (const point of points) {
    if (point.value < min) min = point.value;
    if (point.value > max) max = point.value;
  }
  return {
    count: points.length,
    first: head.value,
    last: points[points.length - 1]?.value ?? head.value,
    min,
    max,
    span: max - min,
  };
}

/* ------------------------------------------------------------------ tone --- */

/**
 * One tone vocabulary for every form. Each component documents which members it
 * honours and what it does with the rest — a donut has no direction to infer, a
 * line has no series to enumerate, and neither should invent one.
 *
 * - `auto`     — infer from direction (ended above or below the baseline)
 * - `positive` / `negative` — force direction
 * - `brand`    — the interactive hue; magnitude with no direction to report
 * - `series`   — the validated four-slot categorical palette, then `chartOther`
 * - `neutral`  — ink; the mark is context for something else on screen
 */
export type ChartTone = 'auto' | 'positive' | 'negative' | 'brand' | 'series' | 'neutral';

/**
 * Resolves a single hue. `series` has no single answer, so it falls back to
 * brand here — components that genuinely enumerate categories call
 * `seriesPalette` instead and never route through this.
 */
export function toneColor(
  t: Tokens,
  tone: ChartTone,
  { rising = true }: { rising?: boolean } = {},
): string {
  switch (tone) {
    case 'positive':
      return t.colors.chartPositive;
    case 'negative':
      return t.colors.chartNegative;
    case 'neutral':
      return t.colors.textSecondary;
    case 'brand':
    case 'series':
      return t.colors.interactivePrimary;
    case 'auto':
    default:
      return rising ? t.colors.chartPositive : t.colors.chartNegative;
  }
}

/**
 * The four validated categorical slots. There is no fifth: anything past the end
 * folds into `chartOther` rather than inventing a hue that reads as a new
 * identity but was never checked for separation.
 */
export function seriesPalette(t: Tokens): string[] {
  return [
    t.colors.chartSeries1,
    t.colors.chartSeries2,
    t.colors.chartSeries3,
    t.colors.chartSeries4,
  ];
}

export function seriesColorAt(t: Tokens, index: number): string {
  const palette = seriesPalette(t);
  return index < palette.length ? (palette[index] as string) : t.colors.chartOther;
}

/* --------------------------------------------------- density and chrome --- */

/**
 * How much mark there is. Two members, closed, Card-style — the axis exists so
 * a chart can shrink into a row or a cell without every call site hand-tuning a
 * stroke width.
 */
export type ChartDensity = 'compact' | 'default';

/**
 * What furniture the plot draws around the data. There is no `axis` member and
 * there will not be one: ticks and gridlines are how a chart this size stops
 * being readable.
 *
 * - `none`      — the mark alone
 * - `baseline`  — a dashed rule at the baseline value
 * - `reference` — one labelled line at a value you name. Not a band system.
 */
export type ChartChrome = 'none' | 'baseline' | 'reference';

/** Closed payload. Anything richer than one line with one label is a later RFC. */
export type ChartReference = { value: number; label?: string };

export type DensityMetrics = {
  stroke: number;
  /** Radius of the scrub dot / end dot. */
  dot: number;
  barRadius: number;
  /** Gap between bars and between donut slices. */
  gap: number;
  /** Category and value labels are the first thing to go when space is tight. */
  showLabels: boolean;
  labelSize: number;
  /** Padding that keeps a stroke or a dot from clipping at the edge of the box. */
  inset: number;
};

export function densityMetrics(density: ChartDensity): DensityMetrics {
  return density === 'compact'
    ? { stroke: 1.5, dot: 4, barRadius: 2, gap: 1, showLabels: false, labelSize: 10, inset: 4 }
    : { stroke: 2, dot: 6, barRadius: 4, gap: 2, showLabels: true, labelSize: 11, inset: 6 };
}

/* -------------------------------------------------------------- geometry --- */

export type Pt = { x: number; y: number };

export type Scale = {
  /** Index -> x, across the usable track. */
  x: (index: number) => number;
  /** Value -> y, with the SVG y-axis pointing down. */
  y: (value: number) => number;
  /** x -> nearest index, clamped. The inverse the scrub needs. */
  indexAt: (x: number) => number;
};

/**
 * One scale, built once per layout and shared by everything that draws or reads.
 * A flat series has no range to normalise against, so it runs down the middle
 * rather than dividing by zero.
 */
export function makeScale({
  count,
  min,
  span,
  width,
  height,
  inset,
}: {
  count: number;
  min: number;
  span: number;
  width: number;
  height: number;
  inset: number;
}): Scale {
  const usableW = Math.max(0, width - inset * 2);
  const usableH = Math.max(0, height - inset * 2);
  const x = (index: number) =>
    count < 2 ? inset + usableW / 2 : inset + (index / (count - 1)) * usableW;
  const y = (value: number) => {
    const ratio = span === 0 ? 0.5 : (value - min) / span;
    return inset + (1 - ratio) * usableH;
  };
  const indexAt = (position: number) => {
    if (count < 2 || usableW <= 0) return 0;
    const index = Math.round(((position - inset) / usableW) * (count - 1));
    return Math.min(count - 1, Math.max(0, index));
  };
  return { x, y, indexAt };
}

/**
 * How the path joins its points. `'steep'` is the default and the honest one —
 * straight segments say only what the data says. `'smooth'` fits a spline, which
 * reads calmer but invents peaks and troughs between points that were never
 * measured.
 */
export type ChartCurve = 'steep' | 'smooth';

const f = (n: number) => (Number.isFinite(n) ? n.toFixed(2) : '0');

/**
 * Catmull-Rom through the points, converted to cubic Béziers. The spline passes
 * through every sample — a plain Bézier control-point fit would not, and a chart
 * whose line misses its own data is worse than a jagged one.
 */
function smoothPath(points: readonly Pt[]): string {
  const first = points[0];
  if (!first) return '';
  if (points.length < 3) {
    return points.map((p, i) => `${i === 0 ? 'M' : 'L'}${f(p.x)},${f(p.y)}`).join(' ');
  }
  let d = `M${f(first.x)},${f(first.y)}`;
  for (let i = 0; i < points.length - 1; i += 1) {
    const p0 = points[i - 1] ?? points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] ?? p2;
    if (!p0 || !p1 || !p2 || !p3) continue;
    // Standard Catmull-Rom -> cubic conversion at tension 0.5.
    const c1 = { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 };
    const c2 = { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 };
    d += ` C${f(c1.x)},${f(c1.y)} ${f(c2.x)},${f(c2.y)} ${f(p2.x)},${f(p2.y)}`;
  }
  return d;
}

export function linePath(points: readonly Pt[], curve: ChartCurve = 'steep'): string {
  if (points.length === 0) return '';
  if (curve === 'smooth') return smoothPath(points);
  return points.map((p, i) => `${i === 0 ? 'M' : 'L'}${f(p.x)},${f(p.y)}`).join(' ');
}

/** The line, closed down to `floorY` and back, for the gradient fill under it. */
export function areaPath(
  points: readonly Pt[],
  floorY: number,
  curve: ChartCurve = 'steep',
): string {
  const line = linePath(points, curve);
  const start = points[0];
  const end = points[points.length - 1];
  if (!line || !start || !end) return '';
  return `${line} L${f(end.x)},${f(floorY)} L${f(start.x)},${f(floorY)} Z`;
}

/**
 * A bar with only its data end rounded. A bar is anchored to its baseline;
 * rounding the anchored end lifts it off and misreports where zero is — so the
 * corner radius is a property of which end carries the datum, not of the shape.
 */
export function barPath({
  x,
  y,
  width,
  height,
  radius,
  roundedEnd,
}: {
  x: number;
  y: number;
  width: number;
  height: number;
  radius: number;
  /**
   * The end that carries the datum: `'top'` for a positive vertical bar,
   * `'bottom'` for one hanging below the baseline, `'right'`/`'left'` for the
   * horizontal layout where the value axis runs across.
   */
  roundedEnd: 'top' | 'bottom' | 'right' | 'left';
}): string {
  const h = Math.max(0, height);
  const w = Math.max(0, width);
  const r = Math.max(0, Math.min(radius, w / 2, h));
  if (w === 0 || h === 0) return '';
  if (r === 0) {
    return `M${f(x)},${f(y)} L${f(x + w)},${f(y)} L${f(x + w)},${f(y + h)} L${f(x)},${f(y + h)} Z`;
  }
  if (roundedEnd === 'top') {
    return [
      `M${f(x)},${f(y + r)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x + r)},${f(y)}`,
      `L${f(x + w - r)},${f(y)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x + w)},${f(y + r)}`,
      `L${f(x + w)},${f(y + h)}`,
      `L${f(x)},${f(y + h)}`,
      'Z',
    ].join(' ');
  }
  if (roundedEnd === 'bottom') {
    return [
      `M${f(x)},${f(y)}`,
      `L${f(x + w)},${f(y)}`,
      `L${f(x + w)},${f(y + h - r)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x + w - r)},${f(y + h)}`,
      `L${f(x + r)},${f(y + h)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x)},${f(y + h - r)}`,
      'Z',
    ].join(' ');
  }
  if (roundedEnd === 'right') {
    return [
      `M${f(x)},${f(y)}`,
      `L${f(x + w - r)},${f(y)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x + w)},${f(y + r)}`,
      `L${f(x + w)},${f(y + h - r)}`,
      `A${f(r)},${f(r)} 0 0 1 ${f(x + w - r)},${f(y + h)}`,
      `L${f(x)},${f(y + h)}`,
      'Z',
    ].join(' ');
  }
  return [
    `M${f(x + r)},${f(y)}`,
    `L${f(x + w)},${f(y)}`,
    `L${f(x + w)},${f(y + h)}`,
    `L${f(x + r)},${f(y + h)}`,
    `A${f(r)},${f(r)} 0 0 1 ${f(x)},${f(y + h - r)}`,
    `L${f(x)},${f(y + r)}`,
    `A${f(r)},${f(r)} 0 0 1 ${f(x + r)},${f(y)}`,
    'Z',
  ].join(' ');
}

/**
 * The shaded band between two bounds — the "likely range" behind a projection.
 * Across the upper bound left to right, back along the lower bound right to
 * left, closed. The two sides may sample different point counts; each is placed
 * by its own index, so a wider forecast band simply has more vertices.
 */
export function bandPath(
  upper: readonly Pt[],
  lower: readonly Pt[],
  curve: ChartCurve = 'steep',
): string {
  if (upper.length === 0 || lower.length === 0) return '';

  /*
   * The band takes the same curve as the line it belongs to.
   *
   * It used to be straight-segment only, which meant a smooth plot drew a fitted
   * spline over a hard-cornered band — two different readings of the same
   * points, stacked. `curve` is one decision about how the data is interpolated,
   * so every mark on the plot has to answer to it.
   *
   * `linePath` opens with `M`; the return leg has to continue the same subpath,
   * so its leading `M` becomes an `L` down to the last lower point.
   */
  const forward = linePath(upper, curve);
  const back = linePath([...lower].reverse(), curve).replace(/^M/, 'L');
  return `${forward} ${back} Z`;
}

/**
 * A stroked arc — the gauge's track, and the path its fill sweeps along.
 *
 * Distinct from `annulusPath`, which returns a *filled* wedge between two radii.
 * A gauge is a stroke: one radius, a `strokeWidth`, and round caps, so the fill
 * can be animated with `strokeDasharray` exactly the way the full ring already
 * is. Building it as a wedge instead would mean animating a `d` string on every
 * frame.
 *
 * Angles follow the same convention as the rest of the file: 0 is twelve
 * o'clock and positive runs clockwise.
 */
export function arcPath({
  cx,
  cy,
  radius,
  startAngle,
  endAngle,
}: {
  cx: number;
  cy: number;
  radius: number;
  startAngle: number;
  endAngle: number;
}): string {
  const sweep = endAngle - startAngle;
  if (sweep <= 0 || radius <= 0) return '';
  const at = (angle: number) => ({
    x: cx + radius * Math.sin(angle),
    y: cy - radius * Math.cos(angle),
  });
  // A lone arc command cannot express a full turn — the endpoints coincide and
  // nothing is drawn — so a full sweep goes round in two halves.
  const TAU = Math.PI * 2;
  if (sweep >= TAU - 1e-6) {
    const a = at(startAngle);
    const b = at(startAngle + Math.PI);
    return `M${f(a.x)},${f(a.y)} A${f(radius)},${f(radius)} 0 0 1 ${f(b.x)},${f(b.y)} A${f(radius)},${f(radius)} 0 0 1 ${f(a.x)},${f(a.y)}`;
  }
  const from = at(startAngle);
  const to = at(endAngle);
  const largeArc = sweep > Math.PI ? 1 : 0;
  return `M${f(from.x)},${f(from.y)} A${f(radius)},${f(radius)} 0 ${largeArc} 1 ${f(to.x)},${f(to.y)}`;
}

/** Length of that arc, for `strokeDasharray`. */
export function arcLength(radius: number, sweep: number): number {
  return Math.max(0, radius * sweep);
}

/**
 * One slice of a ring, as a real annulus — outer arc out, inner arc back, closed.
 *
 * This is the whole reason the donut no longer takes a `centerColor`. Painting a
 * disc over the middle of a pie only reads as a ring when the disc matches what
 * is behind the chart, which is a promise no component can keep on a gradient, a
 * photo, or glass. A cut hole is a hole on all of them.
 *
 * Angles are radians clockwise from 12 o'clock, which is where a part-to-whole
 * ring is read from.
 */
export function annulusPath({
  cx,
  cy,
  outerRadius,
  innerRadius,
  startAngle,
  endAngle,
}: {
  cx: number;
  cy: number;
  outerRadius: number;
  innerRadius: number;
  startAngle: number;
  endAngle: number;
}): string {
  const sweep = endAngle - startAngle;
  if (sweep <= 0 || outerRadius <= 0) return '';
  const TAU = Math.PI * 2;
  const at = (radius: number, angle: number) => ({
    x: cx + radius * Math.sin(angle),
    y: cy - radius * Math.cos(angle),
  });

  // A single arc command cannot express a full turn — start and end coincide, so
  // the renderer draws nothing. A lone slice covering the whole ring goes round
  // in two halves instead.
  if (sweep >= TAU - 1e-6) {
    const mid = startAngle + Math.PI;
    const o1 = at(outerRadius, startAngle);
    const o2 = at(outerRadius, mid);
    const i1 = at(innerRadius, startAngle);
    const i2 = at(innerRadius, mid);
    const outer = `M${f(o1.x)},${f(o1.y)} A${f(outerRadius)},${f(outerRadius)} 0 0 1 ${f(o2.x)},${f(o2.y)} A${f(outerRadius)},${f(outerRadius)} 0 0 1 ${f(o1.x)},${f(o1.y)} Z`;
    if (innerRadius <= 0) return outer;
    // Reversed sweep so the even-odd/nonzero fill leaves the middle empty.
    const inner = `M${f(i1.x)},${f(i1.y)} A${f(innerRadius)},${f(innerRadius)} 0 0 0 ${f(i2.x)},${f(i2.y)} A${f(innerRadius)},${f(innerRadius)} 0 0 0 ${f(i1.x)},${f(i1.y)} Z`;
    return `${outer} ${inner}`;
  }

  const largeArc = sweep > Math.PI ? 1 : 0;
  const oStart = at(outerRadius, startAngle);
  const oEnd = at(outerRadius, endAngle);
  if (innerRadius <= 0) {
    return [
      `M${f(cx)},${f(cy)}`,
      `L${f(oStart.x)},${f(oStart.y)}`,
      `A${f(outerRadius)},${f(outerRadius)} 0 ${largeArc} 1 ${f(oEnd.x)},${f(oEnd.y)}`,
      'Z',
    ].join(' ');
  }
  const iEnd = at(innerRadius, endAngle);
  const iStart = at(innerRadius, startAngle);
  return [
    `M${f(oStart.x)},${f(oStart.y)}`,
    `A${f(outerRadius)},${f(outerRadius)} 0 ${largeArc} 1 ${f(oEnd.x)},${f(oEnd.y)}`,
    `L${f(iEnd.x)},${f(iEnd.y)}`,
    `A${f(innerRadius)},${f(innerRadius)} 0 ${largeArc} 0 ${f(iStart.x)},${f(iStart.y)}`,
    'Z',
  ].join(' ');
}

/* ----------------------------------------------------------------- morph --- */

/**
 * Resamples a series to `count` points by linear interpolation over position.
 *
 * This is the whole trick behind the period morph. "1W" and "1Y" are different
 * *lengths*, and you cannot interpolate between arrays of different lengths — so
 * both ends are resampled onto a common length first, and then it is just a
 * number-to-number tween per point.
 *
 * Resampling for the tween only. The rendered series is always the real one; a
 * resampled series is what the chart looks like mid-flight, never what it lands
 * on.
 */
export function resample(values: readonly number[], count: number): number[] {
  if (count <= 0) return [];
  if (values.length === 0) return new Array<number>(count).fill(0);
  if (values.length === 1) return new Array<number>(count).fill(values[0] as number);
  if (values.length === count) return [...values];

  const out: number[] = [];
  const lastIndex = values.length - 1;
  for (let i = 0; i < count; i += 1) {
    const position = count === 1 ? 0 : (i / (count - 1)) * lastIndex;
    const lower = Math.floor(position);
    const upper = Math.min(lastIndex, lower + 1);
    const t = position - lower;
    const a = values[lower] as number;
    const b = values[upper] as number;
    out.push(a + (b - a) * t);
  }
  return out;
}

/** Per-point tween between two equal-length series. */
export function interpolateSeries(
  from: readonly number[],
  to: readonly number[],
  t: number,
): number[] {
  return to.map((value, index) => {
    const start = from[index] ?? value;
    return start + (value - start) * t;
  });
}

/**
 * Arlo UI — Chart hooks
 *
 * The behaviours every form shares. They live here rather than in `chart.tsx`
 * because `Chart` imports the other four forms to build its namespace — a form
 * reaching back into `chart.tsx` for a hook would close that loop.
 */
import { useCallback, useEffect, useState } from 'react';
import { Animated, Easing } from 'react-native';

/**
 * Re-exported, not re-implemented. Reduce Motion is one answer for the whole
 * app and lives in `foundation/reduce-motion`; this keeps the import path the
 * chart files (and anyone who copied them) already use.
 */
export { useReduceMotion } from '../../foundation/reduce-motion';

// Imported as well as re-exported: `useSkeletonPulse` below reads it directly.
import { useReduceMotion } from '../../foundation/reduce-motion';

/**
 * Controlled-or-uncontrolled, one contract for the root's scrub and for `Bar` and
 * `Donut`'s selection. Passing the index hands you the state; leaving it off
 * keeps it inside while the callback still reports every change, so a chart is
 * useful before you have decided where selection lives.
 */
export function useControllableIndex(
  controlled: number | null | undefined,
  defaultValue: number | null = null,
): [number | null, (next: number | null) => void] {
  const [internal, setInternal] = useState<number | null>(defaultValue);
  const isControlled = controlled !== undefined;
  const value = isControlled ? controlled : internal;
  const set = useCallback(
    (next: number | null) => {
      if (!isControlled) setInternal(next);
    },
    [isControlled],
  );
  return [value ?? null, set];
}

/**
 * Mirrors the user's Reduce Motion setting.
 *
 * Charts consult this for entrances and for the period morph. They deliberately
 * do **not** consult it for scrub: that is direct manipulation, and a crosshair
 * that stopped following the finger would read as broken rather than as calm.
 */

/**
 * The skeleton pulse every form loads with.
 *
 * One hook rather than a copy per form so all five breathe on the same clock —
 * a StatCard sparkline and the Bar chart under it loading out of phase reads as
 * two unrelated things failing, not as one screen filling in.
 *
 * Charts skeleton rather than spin: the silhouette holds the space the marks
 * will occupy, so nothing reflows when the data lands. Under Reduce Motion the
 * pulse resolves to a flat resting opacity — still visibly "not the data", with
 * no animation.
 */
export function useSkeletonPulse(durationMs: number): Animated.Value | number {
  const reduceMotion = useReduceMotion();
  const [pulse] = useState(() => new Animated.Value(SKELETON_MIN_OPACITY));

  useEffect(() => {
    if (reduceMotion) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, {
          toValue: SKELETON_MAX_OPACITY,
          duration: durationMs,
          easing: Easing.inOut(Easing.quad),
          useNativeDriver: true,
        }),
        Animated.timing(pulse, {
          toValue: SKELETON_MIN_OPACITY,
          duration: durationMs,
          easing: Easing.inOut(Easing.quad),
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [pulse, reduceMotion, durationMs]);

  return reduceMotion ? SKELETON_REST_OPACITY : pulse;
}

const SKELETON_MIN_OPACITY = 0.35;
const SKELETON_MAX_OPACITY = 0.75;
/** Reduce Motion resting value — the midpoint, so it reads the same weight. */
const SKELETON_REST_OPACITY = 0.55;

/**
 * Arlo UI — Chart formatters
 *
 * Every chart takes a `format` and none of them ship one, which is how the docs
 * ended up demonstrating a `money` helper that never existed. These are that
 * helper, made real and locale-aware.
 *
 *   <Chart data={points} format={formatMoney('USD')} />
 *   <Chart.Meter value={0.62} format={formatPercent()} />
 *
 * Both are factories rather than bare functions: currency and locale are decided
 * once at the call site, and what comes back is the `(value: number) => string`
 * every chart's `format` prop already accepts.
 *
 * `Intl` is in every JS engine React Native ships on — Hermes has had full ICU
 * since RN 0.73. Passing `locale: undefined` (the default) uses the device's
 * locale, which is what you want for a number the user reads as money.
 */

export type FormatMoneyOptions = {
  /** BCP-47 tag. Defaults to the device locale. */
  locale?: string;
  /**
   * Fraction digits. Defaults to the currency's own convention (2 for USD, 0 for
   * JPY). Pass `0` for the axis-free, glanceable case where cents are noise.
   */
  fractionDigits?: number;
  /** Render 12_400 as "$12.4K". Off by default — an exact number is the honest one. */
  compact?: boolean;
};

/**
 * Currency formatter. The currency code is required because there is no sane
 * default: a chart that guesses USD is wrong everywhere else, silently.
 *
 *   const money = formatMoney('USD');            // $1,240.50
 *   const tight = formatMoney('USD', { fractionDigits: 0, compact: true });  // $1.2K
 */
export function formatMoney(
  currency: string,
  { locale, fractionDigits, compact = false }: FormatMoneyOptions = {},
): (value: number) => string {
  const formatter = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    notation: compact ? 'compact' : 'standard',
    ...(fractionDigits != null
      ? { minimumFractionDigits: fractionDigits, maximumFractionDigits: fractionDigits }
      : null),
  });
  return (value: number) => formatter.format(value);
}

export type FormatPercentOptions = {
  locale?: string;
  /** Decimal places. Defaults to 1 — enough to show movement, short enough to read. */
  fractionDigits?: number;
  /**
   * Whether the input is already a percentage. `Intl` expects a fraction (0.62 →
   * "62%"), but chart series are just as often stored as 62. Say which you have.
   */
  scale?: 'fraction' | 'percent';
};

/**
 *   formatPercent()                       // 0.6234 -> "62.3%"
 *   formatPercent({ scale: 'percent' })   // 62.34  -> "62.3%"
 */
export function formatPercent({
  locale,
  fractionDigits = 1,
  scale = 'fraction',
}: FormatPercentOptions = {}): (value: number) => string {
  const formatter = new Intl.NumberFormat(locale, {
    style: 'percent',
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  });
  return (value: number) => formatter.format(scale === 'percent' ? value / 100 : value);
}

/**
 * Plain number with grouping separators, for series that aren't money or a rate.
 * Here so `format` is never left off just because the value is a count.
 */
export function formatNumber({
  locale,
  fractionDigits,
  compact = false,
}: FormatMoneyOptions = {}): (value: number) => string {
  const formatter = new Intl.NumberFormat(locale, {
    notation: compact ? 'compact' : 'standard',
    ...(fractionDigits != null
      ? { minimumFractionDigits: fractionDigits, maximumFractionDigits: fractionDigits }
      : null),
  });
  return (value: number) => formatter.format(value);
}

/**
 * Arlo UI — Sparkline
 *
 * A line with everything else removed: no axes, no labels, no scrub, no legend.
 * It belongs inline — beside a number in a stat card, inside a table row — where
 * the surrounding text already says what the number is and the shape is the only
 * thing the mark has to carry.
 *
 * If you want a value readout, a baseline, or scrubbing, you want `Chart`.
 *
 * This was the first form to draw its own path, and the geometry it used is now
 * shared: it measures through the same `makeScale` and `linePath` as `Chart.Plot`,
 * so a sparkline and a plot of the same series have the same shape.
 */
import { useId, useMemo, useState } from 'react';
import {
  Text,
  Animated,
  StyleSheet,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Circle, Defs, LinearGradient, Path, Stop } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';
import {
  areaPath,
  densityMetrics,
  linePath,
  makeScale,
  seriesStats,
  toPoints,
  toneColor,
  type ChartCurve,
  type ChartData,
  type ChartDensity,
  type ChartTone,
} from './core';
import { EmptyContent, type ChartEmptyProps } from './empty';
import { useSkeletonPulse } from './hooks';

export type SparklineProps = {
  data: ChartData;
  /**
   * Honours `auto` (default; tones by whether the series ended above where it
   * started), `positive`, `negative`, `brand`, and `neutral`. One series has no
   * categories, so `series` is treated as `brand`.
   */
  tone?: ChartTone;
  /** Inline marks default to `compact`: a thinner stroke and a smaller dot. */
  density?: ChartDensity;
  width?: number;
  height?: number;
  /** Fade a gradient under the line. Off by default — inline marks stay light. */
  fill?: boolean;
  /** Dot on the final point, for "where it ended up". */
  showEndDot?: boolean;
  /**
   * Label the series' own high and low in the margins above and below the mark.
   *
   * These are the *data's* extremes, not an axis: two numbers the series
   * actually reached, which is the same thing `chrome="reference"` draws as a
   * min/max pair on `Chart.Plot`. There is still no scale, no ticks, and no
   * gridlines — the rule the chart core sets out holds.
   *
   * Reserves a row top and bottom, so the mark shrinks rather than running under
   * the text.
   */
  showExtremes?: boolean;
  /** Formats the extreme labels. Raw values when omitted. */
  format?: (value: number) => string;
  /**
   * Short text in place of the mark when there is no data — the same minimum
   * every other chart form has.
   *
   * No default, because the inline case genuinely has none: a 28pt row in a list
   * has no room for words, and the hairline dash is the honest answer there.
   * Give a label wherever the sparkline is big enough to read one.
   */
  emptyLabel?: string;
  /**
   * The composed empty slot — headline, one line, one action — the same one
   * `Chart.Empty`, `Chart.Bar`, and `Chart.Donut` draw. Replaces the mark, so it
   * needs a sparkline given real height; an inline one cannot hold it.
   *
   * Wins over `emptyLabel`.
   */
  empty?: ChartEmptyProps;
  curve?: ChartCurve;
  /** Overrides the density's stroke width. */
  strokeWidth?: number;
  /**
   * Draws the silhouette as a pulsing line instead of the series. Holds the same
   * box, so the row it sits in does not reflow when the data lands.
   */
  loading?: boolean;
  /**
   * Sparklines are decorative next to a value that is already announced, so they
   * are hidden from assistive tech unless you pass a label.
   */
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function Sparkline({
  data,
  tone = 'auto',
  density = 'compact',
  width: widthProp,
  height = 28,
  fill = false,
  showEndDot = false,
  showExtremes = false,
  format,
  emptyLabel,
  empty,
  curve = 'steep',
  strokeWidth,
  loading = false,
  accessibilityLabel,
  style,
}: SparklineProps) {
  const t = useTokens();
  const [measured, setMeasured] = useState(0);
  const width = widthProp ?? measured;
  const metrics = densityMetrics(density);
  const stroke = strokeWidth ?? metrics.stroke;
  // Half a stroke plus the end dot, so neither clips against the edge of the box.
  const inset = showEndDot ? Math.max(metrics.inset, stroke + 1.5) : Math.ceil(stroke / 2) + 1;
  /*
   * Room for the extreme labels, taken out of the mark rather than added around
   * it — a sparkline sits in a fixed slot (a list row, a card header), so it has
   * to keep the height it was given and shrink the line instead.
   */
  const extremeRow = showExtremes ? EXTREME_ROW : 0;
  const plotHeight = Math.max(1, height - extremeRow * 2);

  const points = useMemo(() => toPoints(data), [data]);
  const stats = useMemo(() => seriesStats(points), [points]);
  const color = toneColor(t, tone, { rising: stats.last >= stats.first });

  const plotted = useMemo(() => {
    if (width === 0 || points.length === 0) return [];
    const scale = makeScale({
      count: points.length,
      min: stats.min,
      span: stats.span,
      width,
      height: plotHeight,
      inset,
    });
    return points.map((point, index) => ({
      x: scale.x(index),
      y: scale.y(point.value) + extremeRow,
    }));
  }, [points, width, plotHeight, extremeRow, inset, stats.min, stats.span]);

  const line = linePath(plotted, curve);
  const area = fill ? areaPath(plotted, height - inset - extremeRow, curve) : '';
  const end = plotted[plotted.length - 1];

  // Per instance, not per tone: two `tone="auto"` sparklines on one screen resolve
  // to different colours but would share one document-global gradient id, so the
  // first definition would win and paint both fills the same.
  const gradientId = `arloSparkFill-${useId().replace(/[^a-zA-Z0-9]/g, '')}`;

  /*
   * The composed slot replaces the mark outright, exactly as it does on the
   * donut — it cannot live inside the sparkline's box.
   *
   * A sparkline is 28pt tall inline and 56pt standalone; the slot's icon tile
   * alone is 52pt. Rendering it into an `absoluteFill` inside that fixed height
   * crushed it, which is why it did not look like the empty state on any other
   * form. Returning early lets the content set its own height, the way every
   * other chart's slot does.
   *
   * Keyed off the data rather than the plotted points: `plotted` is also empty
   * before the first measurement, and a chart that flashes its empty state on
   * mount is worse than one that waits a frame.
   */
  if (empty && !loading && points.length === 0) {
    return (
      <View style={[{ width: widthProp, justifyContent: 'center' }, style]}>
        <EmptyContent {...empty} />
      </View>
    );
  }

  return (
    <View
      onLayout={
        widthProp == null
          ? (event: LayoutChangeEvent) => setMeasured(event.nativeEvent.layout.width)
          : undefined
      }
      accessible={accessibilityLabel != null}
      accessibilityRole={accessibilityLabel != null ? 'image' : undefined}
      accessibilityLabel={accessibilityLabel}
      accessibilityElementsHidden={accessibilityLabel == null}
      importantForAccessibility={accessibilityLabel == null ? 'no-hide-descendants' : 'auto'}
      style={[{ width: widthProp, height }, style]}
    >
      {/*
        Outside the SVG, so they take the app's type ramp rather than SVG's own
        text metrics — the same reason the bar chart draws its value labels this
        way. Mono, because two stacked figures have to align digit for digit.
      */}
      {showExtremes && !loading && plotted.length > 0 ? (
        <>
          <ExtremeLabel top text={`H ${format ? format(stats.max) : stats.max}`} />
          <ExtremeLabel top={false} text={`L ${format ? format(stats.min) : stats.min}`} />
        </>
      ) : null}

      {loading ? (
        <SparklineSkeleton width={width} height={height} inset={inset} />
      ) : null}

      {/*
        Empty is a flat rule at the baseline, never a "No data" caption: a
        sparkline is inline beside a number that already carries the label, and a
        28px box has no room for text. The rule holds the height so the row keeps
        its rhythm.
      */}
      {/*
        Words when there is room for them, the dash when there is not.

        The mark alone said nothing about *why* it was blank, which is the one
        thing the other forms all manage — they each fall back to a short label.
        A sparkline cannot always afford one, so this is opt-in rather than a
        default, and the dash stays the answer for a 28pt list row.
      */}
      {!loading && plotted.length === 0 && emptyLabel ? (
        <View style={[StyleSheet.absoluteFill, { alignItems: 'center', justifyContent: 'center' }]}>
          <Text
            numberOfLines={1}
            style={{
              color: t.colors.textTertiary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.bodySm.fontSize,
              lineHeight: t.typography.bodySm.lineHeight,
            }}
          >
            {emptyLabel}
          </Text>
        </View>
      ) : null}

      {!loading && width > 0 && plotted.length === 0 && !emptyLabel ? (
        <Svg width={width} height={height}>
          {/*
            Dashed and hairline, not a solid rule at the data's own weight.

            A solid line across the middle is exactly what a real series with no
            change looks like, so an empty sparkline was indistinguishable from a
            flat one — the chart said "zero" when it meant "nothing". A dash at a
            lighter weight reads as an absence.
          */}
          <Path
            d={`M ${inset} ${height / 2} L ${width - inset} ${height / 2}`}
            stroke={t.colors.borderSecondary}
            strokeWidth={1}
            strokeDasharray="3 4"
            strokeLinecap="round"
          />
        </Svg>
      ) : null}

      {!loading && width > 0 && plotted.length > 0 ? (
        <Svg width={width} height={height}>
          {area ? (
            <>
              <Defs>
                <LinearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                  <Stop offset="0" stopColor={color} stopOpacity={0.24} />
                  <Stop offset="1" stopColor={color} stopOpacity={0} />
                </LinearGradient>
              </Defs>
              <Path d={area} fill={`url(#${gradientId})`} />
            </>
          ) : null}
          <Path
            d={line}
            stroke={color}
            strokeWidth={stroke}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
          {showEndDot && end ? (
            <Circle
              cx={end.x}
              cy={end.y}
              // `stroke + 1.5` — 3.5pt at the default 2pt stroke, which is what
              // the design draws and, more tellingly, exactly what the `inset`
              // above already reserves room for. The dot was drawn at
              // `stroke + 0.5` while the box was measured for a bigger one, so
              // the two halves of the same decision disagreed.
              r={stroke + 1.5}
              fill={color}
            />
          ) : null}
        </Svg>
      ) : null}
    </View>
  );
}

/**
 * The pulsing silhouette drawn while `loading`.
 *
 * A fixed rise-and-settle profile, not the real shape and not a random one: a
 * skeleton that reshapes on every render reads as data arriving and a reader will
 * try to interpret it.
 */
/**
 * Height reserved above and below the mark for the high/low labels — the 10pt
 * mono line plus a little air.
 */
const EXTREME_ROW = 13;

const SKELETON_SHAPE = [0.35, 0.5, 0.42, 0.68, 0.58, 0.8, 0.72, 0.9];

/*
 * `surfaceStrong`, the skeleton material the rest of the chart family uses. It
 * was `borderSecondary` — the same value in both themes, so this changes
 * nothing on screen, but a skeleton naming itself after a border is the kind of
 * drift that becomes a real mismatch the moment either token moves.
 */
function SparklineSkeleton({
  width,
  height,
  inset,
}: {
  width: number;
  height: number;
  inset: number;
}) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  if (width === 0) return null;

  const scale = makeScale({
    count: SKELETON_SHAPE.length,
    min: 0,
    span: 1,
    width,
    height,
    inset,
  });
  const shape = SKELETON_SHAPE.map((value, index) => ({ x: scale.x(index), y: scale.y(value) }));

  return (
    <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { opacity: pulse }]}>
      <Svg width={width} height={height}>
        {/*
          Filled, not stroked. This was the only skeleton in the chart family
          drawn as a line — the plot, the bars, and the donut all fill their
          silhouettes — and at a 1.5pt stroke in a 28pt box it read as a faint
          scratch rather than as something arriving. A filled shape carries the
          weight of the mark it stands in for.
        */}
        <Path d={areaPath(shape, height - inset, 'smooth')} fill={t.colors.surfaceStrong} />
      </Svg>
    </Animated.View>
  );
}

/**
 * One extreme, pinned to the margin its value lives in: the high above the mark,
 * the low below it. Left-aligned rather than tracking the point's own x — a
 * label chasing the peak collides with the line the moment the peak is near an
 * edge, and the number is what matters, not where along the series it happened.
 */
function ExtremeLabel({ top, text }: { top: boolean; text: string }) {
  const t = useTokens();
  return (
    <Text
      numberOfLines={1}
      style={{
        position: 'absolute',
        left: 0,
        ...(top ? { top: 0 } : { bottom: 0 }),
        color: t.colors.textTertiary,
        fontFamily: t.fontFamilies.mono,
        fontSize: 10,
        lineHeight: EXTREME_ROW,
      }}
    >
      {text}
    </Text>
  );
}

/**
 * Arlo UI — BarChart
 *
 * Categorical magnitude: spend per day, sessions per channel. Bars are the right
 * form when the categories are discrete and the comparison is "which is bigger" —
 * use `Chart` instead when the x-axis is continuous time.
 *
 *   <Chart.Bar data={[{ label: 'M', value: 32 }, { label: 'T', value: 18 }]} />
 *
 * One chart, three prop families rather than three components:
 *
 *   <Chart.Bar data={sleep} series={[activity]} variant="grouped" legend={['Sleep', 'Activity']} />
 *   <Chart.Bar data={private_} series={[state]} variant="stacked" legend={['Private', 'State']} />
 *   <Chart.Bar data={spend} layout="horizontal" format={money} />
 *
 * Deliberate choices:
 *
 * - **Data-ends are rounded, the baseline end is not.** A bar is anchored to its
 *   axis; rounding the anchored end would lift it off and misreport where zero is.
 *   A stacked pile rounds only at its top — the interior joins are part of the
 *   same bar, not bars of their own.
 * - **Negatives drop below the baseline** rather than being drawn as magnitudes,
 *   and the baseline moves to wherever zero falls. A stacked bar is part-to-total,
 *   so negatives clamp to zero there — a negative share of a whole is not a thing.
 * - **One hue per series.** A single-series bar chart is magnitude, not identity,
 *   so it does not spend the categorical palette; `tone` steers it. The moment a
 *   second series arrives identity is the story, so every series takes its
 *   validated palette slot and `tone` is ignored.
 * - **Selection instead of hover.** Tapping a category reports it and shows its
 *   value; there is no hover on a touch screen. The categories not selected fade
 *   to a light tint of their own colours rather than dropping out, so the shape
 *   of the whole series survives while one category is being read.
 * - **Bars never scale.** A bar's height *is* its datum, so a bar that grows from
 *   zero is animating the number. On a data change they cross-fade in place
 *   (`motion.chart.barSwap`) — the documented exception to the rule that things
 *   entering scale up.
 * - **Layout is a prop, not a form.** `layout="horizontal"` draws the same
 *   categories as ranked rows — label, track, value — for any ranked breakdown.
 *   It renders the first series; ranking two series at once is a table's job.
 *
 * Each category is its own `Pressable`, sized by the same slot arithmetic that
 * places the mark, so the tap target and the rectangle are the same box by
 * construction rather than by agreement with a library's private layout.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Animated,
  Easing,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { rgbaFromHex } from '@arloui/tokens';
import { haptic } from '../../foundation/haptics';
import { useTokens } from '../../foundation/theme-provider';
import {
  barPath,
  densityMetrics,
  seriesColorAt,
  toneColor,
  type ChartChrome,
  type ChartDensity,
  type ChartPoint,
  type ChartReference,
  type ChartTone,
} from './core';
import { EmptyContent, type ChartEmptyProps } from './empty';
import { useControllableIndex, useReduceMotion, useSkeletonPulse } from './hooks';
import { ChartLegend } from './legend';

/** A bar needs a name, so `label` is required here even though `ChartPoint`'s is not. */
export type BarDatum = ChartPoint & {
  label: string;
  /** Overrides the resolved colour for this bar alone. Single-series only. */
  color?: string;
};

/** How two or more series share a category. */
export type BarChartVariant = 'grouped' | 'stacked';

export type BarChartLayout = 'vertical' | 'horizontal';

/**
 * How much of its slot a category's mark takes up.
 *
 * A **fraction**, not a fixed gap. The gap used to be 1–2pt whatever the chart
 * was, which is a different picture at seven bars than at thirty: seven bars in
 * 350pt read as one solid block with hairlines scored into it. A fraction of the
 * slot looks the same at any count, which is what makes it a token rather than a
 * number someone tuned for one screenshot.
 *
 * `default` is 0.78 — the ratio the design file uses (a 34pt bar in a 44pt slot).
 */
export type BarChartSpacing = 'tight' | 'default' | 'loose';

const SPACING_FILL: Record<BarChartSpacing, number> = {
  tight: 0.94,
  default: 0.78,
  loose: 0.58,
};

/**
 * The same idea on the axis rows run along.
 *
 * Categories in a vertical chart march across the width, so spacing is how much
 * of its slot a bar fills. In a row chart they march *down*, so spacing is the
 * gap between rows. It is one question — how much air is between the marks —
 * asked of whichever axis the categories happen to use, which is why the control
 * should not go dead when the layout flips.
 *
 * A multiplier on the density-provided gap rather than a second set of absolute
 * values: density decides how tight the rows are to begin with, and spacing
 * moves them from there.
 */
const SPACING_ROW_GAP: Record<BarChartSpacing, number> = {
  tight: 0.5,
  default: 1,
  loose: 1.9,
};

export type BarSeries = readonly (BarDatum | number)[];

export type BarChartProps = {
  /** The first series. Bars want labels, so a bare `number[]` gets index labels. */
  data: readonly BarDatum[] | readonly number[];
  /**
   * Additional series, category-for-category with `data`. Two or more series
   * total is where the categorical palette starts and `tone` stops applying.
   */
  series?: readonly BarSeries[];
  /** How the series share each category. Grouped by default. */
  variant?: BarChartVariant;
  /** Series names. Their presence draws the legend; they also name bars to screen readers. */
  legend?: readonly string[];
  /** Vertical bars, or the same categories as ranked horizontal rows. */
  layout?: BarChartLayout;
  /**
   * How much air is between the marks.
   *
   * Vertical: how much of its slot each bar fills — the tap target stays the
   * whole slot, so loosening the bars never shrinks what you can hit.
   * Horizontal: the gap between rows. Same question, whichever axis the
   * categories run along.
   */
  spacing?: BarChartSpacing;
  height?: number;
  /**
   * Honours `brand` (default), `series`, `auto` (colour by sign), `positive`,
   * `negative`, and `neutral` — for a single series. With `series`, every bar
   * takes its own palette slot and this is ignored.
   */
  tone?: ChartTone;
  density?: ChartDensity;
  /**
   * What furniture the plot draws around the data.
   *
   * - `none` — the mark alone: no zero rule, and no rail behind a horizontal row
   * - `baseline` — the zero rule, drawn only when the data crosses zero. Nothing
   *   to draw for an all-positive chart, whose zero is the axis already
   * - `reference` — the above plus one labelled dashed line at a value you name
   *
   * `reference` **adds to** `baseline` rather than replacing it: in a bar chart
   * the zero line is structural, and signed data is unreadable without it.
   *
   * There is no `axis` member.
   */
  chrome?: ChartChrome;
  /** The labelled line drawn when `chrome="reference"`. */
  reference?: ChartReference;
  /** Selected category. Controlled when passed; `defaultActiveIndex` seeds the internal one. */
  activeIndex?: number | null;
  defaultActiveIndex?: number | null;
  onSelect?: (index: number, datum: BarDatum) => void;
  /**
   * Show every category's value. Off by default — a number on every mark is
   * noise. The selected category shows its value regardless, so selection is how
   * you read an exact figure. Multi-series charts show the category total.
   */
  showValues?: boolean;
  /** Show the category label under each bar. Forced off at `density="compact"`. */
  showLabels?: boolean;
  format?: (value: number) => string;
  /** Force the top of the scale; otherwise it comes from the data. */
  maxValue?: number;
  /** Rendered in place of the bars when `data` is empty. */
  emptyLabel?: string;
  /**
   * The composed empty slot — headline, one line, one action — the same one
   * `Chart.Empty` draws. Wins over `emptyLabel`, which stays for the case where
   * a bare string genuinely is the right answer.
   *
   * A bar chart with nothing in it is exactly as empty as a plot with nothing in
   * it, so the two must not say so differently.
   */
  empty?: ChartEmptyProps;
  /**
   * Draws grey bars at a fixed profile instead of the data. Same footprint as the
   * loaded chart — the row does not reflow when the values land, and the labels
   * stay off because a skeleton with real category names is half-loaded, not
   * loading.
   */
  loading?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

/**
 * How much of an unselected category's colour survives. Low enough that the
 * selected one is unmistakably the subject, high enough that the others still
 * read as bars — for the default brand blue this lands on a light blue.
 */
const DIMMED_ALPHA = 0.22;
const LABEL_HEIGHT = 18;
const VALUE_HEIGHT = 16;


function normalizeBars(
  data: readonly (BarDatum | number)[],
  fallbackLabels?: readonly string[],
): BarDatum[] {
  return (data as ReadonlyArray<number | BarDatum>).map((entry, index) =>
    typeof entry === 'number'
      ? { value: entry, label: fallbackLabels?.[index] ?? String(index + 1) }
      : { ...entry, label: entry.label ?? fallbackLabels?.[index] ?? String(index + 1) },
  );
}

/**
 * The silhouette drawn while `loading`.
 *
 * Bars, not a spinner: the skeleton has to hold the same footprint the data will,
 * so the row does not reflow when it lands. The heights are a fixed, unremarkable
 * profile rather than random — a skeleton that reshapes on every render reads as
 * data arriving, and a reader will try to interpret it.
 */
const SKELETON_HEIGHTS = [0.45, 0.7, 0.35, 0.85, 0.55, 0.4, 0.65];

function BarSkeleton({
  width,
  height,
  count,
  spacing,
  radius,
}: {
  width: number;
  height: number;
  count: number;
  spacing: BarChartSpacing;
  radius: number;
}) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  if (width === 0) return null;

  // The same slot arithmetic the loaded chart uses, so the silhouette holds the
  // exact footprint and nothing shifts sideways when the data lands.
  const slot = count > 0 ? width / count : 0;
  const barWidth = Math.max(0, slot * SPACING_FILL[spacing]);
  const markInset = Math.max(0, (slot - barWidth) / 2);
  return (
    <Animated.View
      pointerEvents="none"
      style={[StyleSheet.absoluteFill, { opacity: pulse }]}
    >
      <Svg width={width} height={height}>
        {Array.from({ length: count }, (_, index) => {
          const fraction = SKELETON_HEIGHTS[index % SKELETON_HEIGHTS.length] ?? 0.5;
          const barHeight = height * fraction;
          return (
            <Path
              key={index}
              d={barPath({
                x: index * slot + markInset,
                y: height - barHeight,
                width: barWidth,
                height: barHeight,
                radius,
                roundedEnd: 'top',
              })}
              // `surfaceStrong`, the skeleton material the plot and the readouts
              // use. This was `surfaceInput`, a token lighter in light mode and
              // near-invisible against the surface in dark.
              fill={t.colors.surfaceStrong}
            />
          );
        })}
      </Svg>
    </Animated.View>
  );
}

/**
 * The labelled dashed line — a budget, an average — with its chip at the right
 * edge. The chip is opaque on purpose: it sits over the line it names, so the
 * line can run the full width and the two never have to agree on arithmetic.
 */
function ReferenceLine({ y, width, label }: { y: number; width: number; label: string }) {
  const t = useTokens();
  return (
    <>
      <Svg
        width={width}
        height={1}
        style={{ position: 'absolute', left: 0, top: y }}
        pointerEvents="none"
      >
        <Path
          d={`M0,0.5 L${width.toFixed(2)},0.5`}
          stroke={t.colors.focusRingMain}
          strokeWidth={1}
          strokeDasharray="4 4"
          fill="none"
        />
      </Svg>
      <View
        pointerEvents="none"
        style={{
          position: 'absolute',
          right: 0,
          top: y - 9,
          backgroundColor: t.colors.feedbackInfoBg,
          borderRadius: 6,
          paddingHorizontal: 10,
          paddingVertical: 2,
        }}
      >
        <Text
          style={{
            color: t.colors.textInteractiveTertiary,
            fontFamily: t.fontFamilies.sans,
            fontSize: 10,
            lineHeight: 14,
            fontWeight: '700',
          }}
        >
          {label}
        </Text>
      </View>
    </>
  );
}

export function BarChart(props: BarChartProps) {
  const { layout = 'vertical' } = props;
  return layout === 'horizontal' ? <HorizontalBars {...props} /> : <VerticalBars {...props} />;
}

function VerticalBars({
  data,
  series,
  variant = 'grouped',
  legend,
  spacing = 'default',
  height = 160,
  tone = 'brand',
  density = 'default',
  chrome = 'baseline',
  reference,
  activeIndex: activeIndexProp,
  defaultActiveIndex = null,
  onSelect,
  showValues = false,
  showLabels = true,
  format,
  maxValue,
  emptyLabel = 'No data',
  empty,
  loading = false,
  accessibilityLabel,
  style,
}: BarChartProps) {
  const t = useTokens();
  const [width, setWidth] = useState(0);
  const metrics = densityMetrics(density);
  const reduceMotion = useReduceMotion();
  const [selection, setSelection] = useControllableIndex(activeIndexProp, defaultActiveIndex);

  const allSeries = useMemo(() => {
    const first = normalizeBars(data);
    const labels = first.map((bar) => bar.label);
    return [first, ...(series ?? []).map((extra) => normalizeBars(extra, labels))];
  }, [data, series]);
  const bars = allSeries[0] as BarDatum[];
  const seriesCount = allSeries.length;
  const stacked = seriesCount > 1 && variant === 'stacked';
  const grouped = seriesCount > 1 && !stacked;

  const withLabels = showLabels && metrics.showLabels;

  const { top, bottom } = useMemo(() => {
    if (bars.length === 0) return { top: 0, bottom: 0 };
    let hi = 0;
    let lo = 0;
    if (stacked) {
      // Part-to-total: the ceiling is the tallest pile, negatives don't count.
      for (let index = 0; index < bars.length; index += 1) {
        let total = 0;
        for (const list of allSeries) total += Math.max(0, list[index]?.value ?? 0);
        if (total > hi) hi = total;
      }
    } else {
      for (const list of allSeries) {
        for (const bar of list) {
          if (bar.value > hi) hi = bar.value;
          if (bar.value < lo) lo = bar.value;
        }
      }
    }
    return { top: maxValue ?? hi, bottom: lo };
  }, [bars, allSeries, maxValue, stacked]);

  // The plot always includes zero, so bar lengths stay proportional to value.
  const span = top - bottom;
  const plotHeight = Math.max(0, height - (withLabels ? LABEL_HEIGHT : 0));

  /*
   * Value labels are drawn above the bar top and would clip at the top of the
   * plot, so the scale gives up a label's height of ceiling. Bars stay
   * proportional to each other — only the ceiling moves.
   *
   * The room is reserved for any chart that could ever show a value, not just one
   * showing them now: a selection can put a label over the tallest bar, and
   * reserving on selection instead would resize every bar on each tap.
   *
   * `reserved` is a top offset, not just a shorter drawing height. Shortening the
   * height alone leaves the tallest bar's top at y=0 with the spare room stranded
   * under the baseline, and its label — clamped to the top of the box — lands
   * inside the bar.
   */
  const canShowValues = showValues || onSelect != null || activeIndexProp !== undefined;
  const reserved = canShowValues && plotHeight > VALUE_HEIGHT ? VALUE_HEIGHT : 0;
  const drawHeight = plotHeight - reserved;

  /**
   * Value -> y within the plot box, with zero wherever the data puts it. Bars are
   * anchored to the floor (`plotHeight`) and grow up into `drawHeight`, so the
   * reserved band is the strip above the tallest bar.
   */
  const yFor = useCallback(
    (value: number) => {
      if (span === 0) return plotHeight;
      return plotHeight - ((value - bottom) / span) * drawHeight;
    },
    [span, bottom, drawHeight, plotHeight],
  );

  const zeroY = yFor(0);

  const seriesColor = useCallback(
    (seriesIndex: number, datum: BarDatum, categoryIndex: number) => {
      if (seriesCount > 1) return seriesColorAt(t, seriesIndex);
      if (datum.color) return datum.color;
      // A single measure asked to spend the palette colours per category —
      // each bar really is a different thing.
      if (tone === 'series') return seriesColorAt(t, categoryIndex);
      return toneColor(t, tone, { rising: datum.value >= 0 });
    },
    [seriesCount, tone, t],
  );

  const seriesName = useCallback(
    (index: number) => legend?.[index] ?? `Series ${index + 1}`,
    [legend],
  );

  /** The number the value label shows for a category: the pile's top when stacked. */
  const categoryTotal = useCallback(
    (index: number) => {
      if (!stacked) return allSeries.reduce((sum, list) => sum + (list[index]?.value ?? 0), 0);
      return allSeries.reduce((sum, list) => sum + Math.max(0, list[index]?.value ?? 0), 0);
    },
    [allSeries, stacked],
  );

  const formatValue = useCallback(
    (value: number) => (format ? format(value) : String(value)),
    [format],
  );

  /*
   * Bars cross-fade on a data change rather than sweeping up from zero. Fading
   * the whole mark layer is the honest version of "the numbers changed"; growing
   * each bar would animate the datum itself.
   */
  const [swap] = useState(() => new Animated.Value(1));
  const signature = allSeries
    .map((list) => list.map((bar) => `${bar.label}:${bar.value}`).join('|'))
    .join('||');
  useEffect(() => {
    if (reduceMotion) {
      swap.setValue(1);
      return;
    }
    swap.setValue(0.35);
    const animation = Animated.timing(swap, {
      toValue: 1,
      duration: t.motion.chart.barSwap.duration,
      easing: Easing.bezier(...t.motion.chart.barSwap.easing),
      useNativeDriver: true,
    });
    animation.start();
    return () => animation.stop();
  }, [signature, swap, reduceMotion, t.motion.chart.barSwap.duration, t.motion.chart.barSwap.easing]);

  const summary =
    accessibilityLabel ??
    (bars.length === 0
      ? emptyLabel
      : `Bar chart, ${bars.length} categories, ${bars
          .map((bar, index) =>
            allSeries
              .map((list, s) => (s === 0 ? `${bar.label} ${list[index]?.value ?? 0}` : list[index]?.value ?? 0))
              .join(', '),
          )
          .join(', ')}`);

  // A container element and focusable children are mutually exclusive, so the
  // chart picks whichever is actually useful: when bars are tappable each one is
  // its own button, and when they aren't the whole chart is a single element
  // announcing the summary.
  const interactive = onSelect != null || activeIndexProp !== undefined;

  // One slot per category, gaps included. The same numbers place the mark and
  // size the tap target, so the two cannot drift.
  /*
   * The slot is the category's full share of the width — tap target, label
   * column, and mark all measure from it, so they cannot drift apart. The mark
   * then fills a *fraction* of that slot and sits centred in it, which is what
   * puts air between bars without moving anything else.
   */
  const slot = bars.length > 0 ? width / bars.length : 0;
  const groupWidth = Math.max(0, slot * SPACING_FILL[spacing]);
  const gap = metrics.gap;
  // Grouped bars split the mark; stacked segments share its full width.
  const barWidth = grouped
    ? Math.max(0, (groupWidth - gap * (seriesCount - 1)) / seriesCount)
    : groupWidth;
  /** Left edge of the mark within its slot. */
  const markInset = Math.max(0, (slot - groupWidth) / 2);

  type Mark = { key: string; d: string; fill: string; opacity: number };

  const marks = useMemo(() => {
    if (width === 0 || bars.length === 0 || loading) return [];
    const out: Mark[] = [];
    const tint = (color: string, dimmed: boolean) =>
      dimmed && color.startsWith('#') ? rgbaFromHex(color, DIMMED_ALPHA) : color;
    const fade = (color: string, dimmed: boolean) =>
      dimmed && !color.startsWith('#') ? DIMMED_ALPHA : 1;

    for (let index = 0; index < bars.length; index += 1) {
      const categoryDimmed = selection != null && selection !== index;
      const categoryX = index * slot + markInset;

      if (stacked) {
        // Segments stack bottom-up in series order; only the pile's data end —
        // its top — is rounded. Interior joins stay square: they are seams in
        // one bar, not bars of their own.
        const segments: { s: number; bottom: number; top: number; datum: BarDatum }[] = [];
        let acc = 0;
        for (let s = 0; s < seriesCount; s += 1) {
          const datum = allSeries[s]?.[index];
          if (!datum) continue;
          const value = Math.max(0, datum.value);
          if (value <= 0) continue;
          segments.push({ s, bottom: acc, top: acc + value, datum });
          acc += value;
        }
        segments.forEach((segment, position) => {
          const yTop = yFor(segment.top);
          const yBottom = yFor(segment.bottom);
          const color = seriesColor(segment.s, segment.datum, index);
          out.push({
            key: `${index}-${segment.s}`,
            d: barPath({
              x: categoryX,
              y: yTop,
              // `barWidth`, not `slot`. A stack is one bar made of segments, so
              // it is exactly as wide as a single bar — and `categoryX` already
              // carries `markInset`, so drawing a full-slot segment at an inset
              // origin pushed the pile over its neighbour.
              width: barWidth,
              height: Math.max(0, yBottom - yTop),
              radius: position === segments.length - 1 ? metrics.barRadius : 0,
              roundedEnd: 'top',
            }),
            fill: tint(color, categoryDimmed),
            opacity: fade(color, categoryDimmed),
          });
        });
      } else {
        for (let s = 0; s < seriesCount; s += 1) {
          const datum = allSeries[s]?.[index];
          if (!datum) continue;
          const negative = datum.value < 0;
          const valueY = yFor(datum.value);
          out.push({
            key: `${index}-${s}`,
            d: barPath({
              x: categoryX + s * (barWidth + gap),
              y: negative ? zeroY : valueY,
              width: barWidth,
              height: Math.abs(valueY - zeroY),
              radius: metrics.barRadius,
              roundedEnd: negative ? 'bottom' : 'top',
            }),
            fill: tint(seriesColor(s, datum, index), categoryDimmed),
            opacity: fade(seriesColor(s, datum, index), categoryDimmed),
          });
        }
      }
    }
    return out;
  }, [
    bars,
    width,
    loading,
    barWidth,
    gap,
    slot,
    markInset,
    seriesCount,
    stacked,
    selection,
    yFor,
    zeroY,
    allSeries,
    metrics.barRadius,
    seriesColor,
  ]);

  /** Where the value label for a category sits: over the tallest mark in it. */
  const labelTopFor = useCallback(
    (index: number) => {
      if (stacked) return yFor(categoryTotal(index));
      let highest = zeroY;
      for (const list of allSeries) {
        const value = list[index]?.value ?? 0;
        highest = Math.min(highest, yFor(Math.max(0, value)));
      }
      return highest;
    },
    [stacked, yFor, categoryTotal, allSeries, zeroY],
  );

  const referenceY = chrome === 'reference' && reference != null ? yFor(reference.value) : null;
  const referenceLabel =
    reference != null ? (reference.label ?? formatValue(reference.value)) : '';

  const legendItems =
    legend != null && seriesCount > 1
      ? allSeries.map((_, s) => ({ label: seriesName(s), color: seriesColorAt(t, s) }))
      : null;

  const handleLayout = useCallback((event: LayoutChangeEvent) => {
    setWidth(event.nativeEvent.layout.width);
  }, []);

  return (
    <View style={[{ gap: t.spacing[2] }, style]}>
      <View
        onLayout={handleLayout}
        accessible={!interactive}
        accessibilityRole={interactive ? undefined : 'image'}
        accessibilityLabel={interactive ? undefined : summary}
        style={[{ height, width: '100%' }]}
      >
        {marks.length > 0 ? (
          <Animated.View
            pointerEvents="none"
            style={{ position: 'absolute', top: 0, left: 0, opacity: reduceMotion ? 1 : swap }}
          >
            <Svg width={width} height={plotHeight}>
              {/*
                Two conditions, and the chrome one was missing.

                The rule only earns its place when the data actually crosses zero
                — an all-positive chart has its zero at the axis already. But it
                also has to answer to `chrome`, which it did not: it drew
                whatever was selected, so `none` was never "the mark alone" and
                `baseline` never turned anything on. `baseline` was a setting
                that did nothing, which is why it read as a duplicate of
                `reference` minus the label.

                `reference` keeps the rule too. In a bar chart the zero line is
                structural — with signed data you cannot read where the axis is
                without it — so it is not something a labelled line replaces.
              */}
              {chrome !== 'none' && bottom < 0 ? (
                <Path
                  d={`M0,${zeroY.toFixed(2)} L${width.toFixed(2)},${zeroY.toFixed(2)}`}
                  stroke={t.colors.borderSecondary}
                  strokeWidth={1}
                  fill="none"
                />
              ) : null}
              {marks.map((mark) => (
                <Path key={mark.key} d={mark.d} fill={mark.fill} opacity={mark.opacity} />
              ))}
            </Svg>
          </Animated.View>
        ) : null}

        {referenceY != null && !loading && width > 0 ? (
          <ReferenceLine y={referenceY} width={width} label={referenceLabel} />
        ) : null}

        {/* Value labels sit outside the SVG so they use the same type ramp as the
            rest of the interface rather than SVG's own text metrics. Single-series
            charts label the one bar; multi-series charts label the category total. */}
        {/*
          Never while loading. These used to render regardless, so a chart with
          `showValues` painted real figures over the grey silhouette — and
          positioned them by `yFor(bar.value)`, the *loaded* geometry, while the
          bars underneath used the fixed skeleton profile. Numbers floating at
          heights nothing on screen agreed with. Same rule as `Chart.Value`: a
          chart does not show a figure before it has one.
        */}
        {loading ? null : seriesCount === 1
          ? bars.map((bar, index) => {
              if (!(showValues || selection === index)) return null;
              const valueY = yFor(bar.value);
              return (
                <View
                  key={`value-${bar.label}-${index}`}
                  pointerEvents="none"
                  style={{
                    position: 'absolute',
                    left: index * slot,
                    width: barWidth,
                    top: Math.max(0, Math.min(valueY, zeroY) - VALUE_HEIGHT),
                    alignItems: 'center',
                  }}
                >
                  <Text
                    numberOfLines={1}
                    style={{
                      color: selection === index ? t.colors.textPrimary : t.colors.textSecondary,
                      fontFamily: t.fontFamilies.sans,
                      fontSize: metrics.labelSize - 1,
                      fontWeight: '600',
                    }}
                  >
                    {formatValue(bar.value)}
                  </Text>
                </View>
              );
            })
          : bars.map((bar, index) => {
              if (!(showValues || selection === index)) return null;
              return (
                <View
                  key={`value-${bar.label}-${index}`}
                  pointerEvents="none"
                  style={{
                    position: 'absolute',
                    left: index * slot,
                    width: slot,
                    top: Math.max(0, labelTopFor(index) - VALUE_HEIGHT),
                    alignItems: 'center',
                  }}
                >
                  <Text
                    numberOfLines={1}
                    style={{
                      color: selection === index ? t.colors.textPrimary : t.colors.textSecondary,
                      fontFamily: t.fontFamilies.sans,
                      fontSize: metrics.labelSize - 1,
                      fontWeight: '600',
                    }}
                  >
                    {formatValue(categoryTotal(index))}
                  </Text>
                </View>
              );
            })}

        {/* Tap targets and category labels. Full-height columns on the same slot
            arithmetic as the marks above — matching the bars' widths is what makes a
            tap land on the right category, and staying full height keeps the target
            comfortable for a short bar.

            Empty while loading: a skeleton you can select is a lie, and these carry
            the real category names and values in their accessibility labels, so
            leaving them mounted would read the not-yet-loaded data out loud. */}
        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'stretch', gap }}>
          {(loading ? [] : bars).map((bar, index) => {
            const selected = selection === index;
            return (
              <Pressable
                key={`${bar.label}-${index}`}
                accessible={interactive}
                accessibilityRole={interactive ? 'button' : undefined}
                accessibilityLabel={
                  interactive
                    ? seriesCount === 1
                      ? `${bar.label}, ${formatValue(bar.value)}`
                      : `${bar.label}, ${allSeries
                          .map((list, s) => `${seriesName(s)} ${formatValue(list[index]?.value ?? 0)}`)
                          .join(', ')}`
                    : undefined
                }
                accessibilityState={interactive ? { selected } : undefined}
                disabled={!interactive}
                onPress={() => {
                  // `selection`, not `impact` — picking one bar out of a row is the
                  // same gesture as moving through a picker.
                  void haptic('selection');
                  setSelection(selected ? null : index);
                  onSelect?.(index, bar);
                }}
                style={{ flex: 1, justifyContent: 'flex-end' }}
              >
                {withLabels ? (
                  <Text
                    numberOfLines={1}
                    style={{
                      height: LABEL_HEIGHT,
                      textAlign: 'center',
                      color: selected ? t.colors.textPrimary : t.colors.textTertiary,
                      fontFamily: t.fontFamilies.sans,
                      fontSize: metrics.labelSize,
                      fontWeight: selected ? '700' : '500',
                    }}
                  >
                    {bar.label}
                  </Text>
                ) : null}
              </Pressable>
            );
          })}
        </View>

        {loading ? (
          <BarSkeleton
            width={width}
            height={plotHeight}
            count={bars.length > 0 ? bars.length : SKELETON_HEIGHTS.length}
            spacing={spacing}
            radius={metrics.barRadius}
          />
        ) : null}

        {bars.length === 0 && !loading ? (
          <View
            /*
             * `box-none`, not `none`: the composed slot can carry an action, and
             * `none` would make that button — the only control on a chart with
             * no data — unpressable.
             */
            pointerEvents="box-none"
            style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, alignItems: 'center', justifyContent: 'center' }}
          >
            {empty ? (
              <EmptyContent {...empty} />
            ) : (
              <Text
                style={{
                  color: t.colors.textTertiary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: t.typography.bodySm.fontSize,
                  lineHeight: t.typography.bodySm.lineHeight,
                }}
              >
                {emptyLabel}
              </Text>
            )}
          </View>
        ) : null}
      </View>

      {legendItems ? <ChartLegend items={legendItems} /> : null}
    </View>
  );
}

/* ------------------------------------------------------------- horizontal --- */

/**
 * The row's corner radius, used by both the rail and the outer end of the fill
 * it holds. One constant because the two have to agree: the rail clips the fill,
 * so a fill rounded to a different radius reads as a rendering fault at
 * whichever end the clip is doing the work.
 */
const ROW_RADIUS = 5;

/**
 * What `density` means for rows.
 *
 * It used to mean almost nothing here: `densityMetrics` moved the label size by
 * a single point and set `showLabels: false`, so the only visible effect of
 * `compact` was hiding the labels — which is what the `showLabels` prop is for.
 * Two controls, one outcome, and the axis that is supposed to say "this chart is
 * going in a small space" said nothing about the rows.
 *
 * It now sizes the rows: the rail, the gaps between them, and the two columns
 * either side. And it no longer forces labels off. A vertical bar's label is a
 * caption underneath it; a **row's** label is the row's identity, so dropping it
 * leaves a list of anonymous bars. Density makes rows tighter; `showLabels`
 * decides whether they are named. Different questions, separate answers.
 */
const ROW_METRICS = {
  default: { height: 16, gap: 8, label: 72, value: 44, font: 11 },
  compact: { height: 10, gap: 5, label: 56, value: 38, font: 10 },
} as const;

/** Gap between the label column, the track, and the value column. */
const COLUMN_GAP = 10;

/**
 * The same categories as ranked rows: label, track, value. A ranked breakdown
 * reads better as rows than as rotated bars, so the horizontal layout is its own
 * render path over the same selection contract — not a second chart.
 *
 * **It answers the same props as the vertical path.** It used to take only
 * `data`, so `tone`, `series`, `variant`, `legend`, `chrome`, `reference`,
 * `showValues`, and `showLabels` were silently dropped the moment
 * `layout="horizontal"` was set — every one of those controls looked live and did
 * nothing, and a grouped or stacked chart quietly collapsed to its first series.
 * A prop that a component accepts and ignores is worse than one it does not
 * accept: there is no error to notice, just a control that does not work.
 */
function HorizontalBars({
  data,
  series,
  variant = 'grouped',
  legend,
  activeIndex: activeIndexProp,
  defaultActiveIndex = null,
  onSelect,
  format,
  maxValue,
  tone = 'brand',
  density = 'default',
  spacing = 'default',
  chrome = 'baseline',
  reference,
  showValues = false,
  showLabels = true,
  emptyLabel = 'No data',
  empty,
  loading = false,
  accessibilityLabel,
  style,
}: BarChartProps) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  const [selection, setSelection] = useControllableIndex(activeIndexProp, defaultActiveIndex);
  const [size, setSize] = useState({ width: 0, height: 0 });
  const width = size.width;

  const allSeries = useMemo(() => {
    const first = normalizeBars(data);
    const labels = first.map((bar) => bar.label);
    return [first, ...(series ?? []).map((extra) => normalizeBars(extra, labels))];
  }, [data, series]);
  const bars = allSeries[0] as BarDatum[];
  const seriesCount = allSeries.length;
  const stacked = seriesCount > 1 && variant === 'stacked';
  const grouped = seriesCount > 1 && !stacked;

  const interactive = onSelect != null || activeIndexProp !== undefined;
  // `showLabels` alone: `metrics.showLabels` is the vertical caption rule, and a
  // row's label is its identity rather than a caption.
  const withLabels = showLabels;
  const row = ROW_METRICS[density === 'compact' ? 'compact' : 'default'];
  const rowGap = Math.round(row.gap * SPACING_ROW_GAP[spacing]);
  /*
   * The rail — the grey track a row's fill sits in — is furniture, so `chrome`
   * governs it like every other piece.
   *
   * It is worth being able to turn off. A rail shows what the fill is a fraction
   * *of*, which is meaningful when the ceiling is a real one — a budget, a goal,
   * anything passed as `maxValue`. With no `maxValue` the ceiling is just the
   * largest row, so the rail is drawn at wherever the biggest item happened to
   * land: it looks like a target and is not one. A ranked breakdown is read by
   * comparing the rows to each other, and seven grey rectangles behind seven
   * coloured ones is noise in that reading.
   */
  const withRail = chrome !== 'none';
  /** Grouped rows split the rail into one thin track per series. */
  const groupRowGap = density === 'compact' ? 2 : 3;
  const groupRowHeight = density === 'compact' ? 8 : 12;

  /*
   * The track spans [floor, ceiling] and always contains zero, so a row's length
   * stays proportional to its value and a negative row reads as one — it grows
   * left from the zero anchor instead of clamping to nothing.
   *
   * The old scale was `value / max` clamped to [0, 1], which meant every negative
   * category rendered as an empty track. An all-negative series drew nothing at
   * all and looked like a loading failure.
   */
  const { floor, ceiling } = useMemo(() => {
    let hi = 0;
    let lo = 0;
    if (stacked) {
      // Part-to-total: the ceiling is the widest pile, negatives don't count.
      for (let index = 0; index < bars.length; index += 1) {
        let total = 0;
        for (const list of allSeries) total += Math.max(0, list[index]?.value ?? 0);
        if (total > hi) hi = total;
      }
    } else {
      for (const list of allSeries) {
        for (const bar of list) {
          if (bar.value > hi) hi = bar.value;
          if (bar.value < lo) lo = bar.value;
        }
      }
    }
    // A zero span would divide by zero; one full-width row is the honest floor.
    return { floor: lo, ceiling: Math.max(maxValue ?? hi, lo + 1) };
  }, [bars, allSeries, maxValue, stacked]);

  const span = ceiling - floor;

  const trackWidth = Math.max(
    0,
    width -
      (withLabels ? row.label + COLUMN_GAP : 0) -
      (row.value + COLUMN_GAP),
  );

  const colorFor = useCallback(
    (seriesIndex: number, datum: BarDatum, categoryIndex: number) => {
      if (seriesCount > 1) return seriesColorAt(t, seriesIndex);
      if (datum.color) return datum.color;
      if (tone === 'series') return seriesColorAt(t, categoryIndex);
      return toneColor(t, tone, { rising: datum.value >= 0 });
    },
    [seriesCount, tone, t],
  );

  const seriesName = useCallback(
    (index: number) => legend?.[index] ?? `Series ${index + 1}`,
    [legend],
  );

  const formatValue = useCallback(
    (value: number) => (format ? format(value) : String(value)),
    [format],
  );

  /** Multi-series rows report the category total, matching the vertical path. */
  const totalAt = useCallback(
    (index: number) =>
      allSeries.reduce((sum, list) => sum + (list[index]?.value ?? 0), 0),
    [allSeries],
  );

  const legendItems =
    legend != null && seriesCount > 1
      ? allSeries.map((_, index) => ({ label: seriesName(index), color: seriesColorAt(t, index) }))
      : null;

  /**
   * Where zero sits across the rail, 0–1. Zero for an all-positive chart, whose
   * fills already start at the rail's left edge.
   */
  const zeroAt = span === 0 ? 0 : (0 - floor) / span;
  /*
   * The zero rule, on the same terms as the vertical path: only when the data
   * actually crosses zero, and only when `chrome` asks for furniture. Rows were
   * missing it entirely — a signed row chart grows its fills left and right of a
   * zero anchor that nothing marked, so there was no way to see where the axis
   * was.
   */
  const showZeroRule = chrome !== 'none' && floor < 0;
  const referenceAt =
    chrome === 'reference' && reference != null && span > 0
      ? (reference.value - floor) / span
      : null;
  /** Left edge of the rail within the row, so the rules line up with the fills. */
  const railLeft = withLabels ? row.label + COLUMN_GAP : 0;
  /** A full-height vertical rule at a 0–1 position across the rail. */
  const ruleAt = (fraction: number) => {
    const x = railLeft + Math.min(Math.max(fraction, 0), 1) * trackWidth;
    return `M${x.toFixed(2)},0 L${x.toFixed(2)},${size.height.toFixed(2)}`;
  };

  const summary =
    accessibilityLabel ??
    (bars.length === 0
      ? emptyLabel
      : `Bar chart, ${bars.length} categories, ${bars
          .map((bar, index) => `${bar.label} ${seriesCount > 1 ? totalAt(index) : bar.value}`)
          .join(', ')}`);

  const skeletonCount = bars.length > 0 ? bars.length : 3;

  const handleLayout = useCallback((event: LayoutChangeEvent) => {
    const { width: w, height: h } = event.nativeEvent.layout;
    setSize((current) => (current.width === w && current.height === h ? current : { width: w, height: h }));
  }, []);

  if (!loading && bars.length === 0) {
    return (
      <View
        accessible
        accessibilityRole="image"
        accessibilityLabel={summary}
        style={[{ minHeight: row.height, alignItems: 'center', justifyContent: 'center' }, style]}
      >
        {empty ? (
          <EmptyContent {...empty} />
        ) : (
          <Text
            style={{
              color: t.colors.textTertiary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.bodySm.fontSize,
              lineHeight: t.typography.bodySm.lineHeight,
            }}
          >
            {emptyLabel}
          </Text>
        )}
      </View>
    );
  }

  /** One filled span inside a track, positioned from the zero anchor. */
  const segment = (
    value: number,
    color: string,
    dimmed: boolean,
    height: number,
    offset = 0,
  ) => {
    const from = Math.min(value, 0);
    const to = Math.max(value, 0);
    const left = span === 0 ? 0 : (from - floor) / span;
    const size = span === 0 ? 0 : (to - from) / span;
    return (
      <View
        style={{
          position: 'absolute',
          left: `${left * 100}%`,
          width: `${size * 100}%`,
          top: offset,
          height,
          borderRadius: ROW_RADIUS,
          backgroundColor: dimmed && color.startsWith('#') ? rgbaFromHex(color, DIMMED_ALPHA) : color,
          opacity: dimmed && !color.startsWith('#') ? DIMMED_ALPHA : 1,
        }}
      />
    );
  };

  return (
    <View style={[{ gap: t.spacing[2] }, style]}>
      <View
        onLayout={handleLayout}
        accessible={!interactive}
        accessibilityRole={interactive ? undefined : 'image'}
        accessibilityLabel={interactive ? undefined : summary}
        style={{ gap: rowGap }}
      >
        {(loading ? Array.from({ length: skeletonCount }, () => null) : bars).map(
          (bar, index) => {
            if (loading) {
              const fraction = SKELETON_HEIGHTS[index % SKELETON_HEIGHTS.length] ?? 0.5;
              return (
                <View key={`skeleton-${index}`} style={{ flexDirection: 'row', alignItems: 'center', gap: COLUMN_GAP }}>
                  {withLabels ? (
                    <View style={{ width: row.label, height: row.font, borderRadius: 3, backgroundColor: t.colors.surfaceInput }} />
                  ) : null}
                  <View
                    style={{
                      flex: 1,
                      height: row.height,
                      borderRadius: ROW_RADIUS,
                      // Matches the loaded chart: a skeleton that shows rails the
                      // real rows will not have is a different layout, not a
                      // preview of one.
                      backgroundColor: withRail ? t.colors.surfaceInput : 'transparent',
                    }}
                  >
                    {/* `Animated.View`, not `View`: the pulse is an Animated.Value, and a
                        plain view hands the native side an object, not a number. */}
                    <Animated.View
                      style={{
                        width: `${Math.round(fraction * 100)}%`,
                        height: '100%',
                        borderRadius: ROW_RADIUS,
                        backgroundColor: t.colors.surfaceStrong,
                        opacity: pulse,
                      }}
                    />
                  </View>
                  <View style={{ width: row.value }} />
                </View>
              );
            }

            const datum = bar as BarDatum;
            const selected = selection === index;
            const dimmed = selection != null && !selected;
            const rowValue = seriesCount > 1 ? totalAt(index) : datum.value;
            const trackHeight = grouped
              ? seriesCount * groupRowHeight + (seriesCount - 1) * groupRowGap
              : row.height;

            // The value is the row's readout, but it stays on the same terms as
            // the vertical path: off unless asked for, and always on for the row
            // being read. The column keeps its width either way so toggling
            // values never reflows the track.
            const valueShown = showValues || selected;

            let stackedFrom = 0;

            return (
              <Pressable
                key={`${datum.label}-${index}`}
                accessible={interactive}
                accessibilityRole={interactive ? 'button' : undefined}
                accessibilityLabel={
                  interactive ? `${datum.label}, ${formatValue(rowValue)}` : undefined
                }
                accessibilityState={interactive ? { selected } : undefined}
                disabled={!interactive}
                onPress={() => {
                  void haptic('selection');
                  setSelection(selected ? null : index);
                  onSelect?.(index, datum);
                }}
                style={({ pressed }) => ({
                  flexDirection: 'row',
                  alignItems: 'center',
                  gap: COLUMN_GAP,
                  opacity: pressed ? t.motion.pressed.opacity : 1,
                  cursor: Platform.OS === 'web' ? 'pointer' : undefined,
                })}
              >
                {withLabels ? (
                  <Text
                    numberOfLines={1}
                    style={{
                      width: row.label,
                      color: t.colors.textSecondary,
                      fontFamily: t.fontFamilies.sans,
                      fontSize: row.font,
                      lineHeight: row.font + 3,
                      fontWeight: '500',
                    }}
                  >
                    {datum.label}
                  </Text>
                ) : null}
                <View
                  style={{
                    flex: 1,
                    height: trackHeight,
                    borderRadius: ROW_RADIUS,
                    backgroundColor: withRail ? t.colors.surfaceInput : 'transparent',
                    overflow: 'hidden',
                  }}
                >
                  {grouped
                    ? allSeries.map((list, s) => {
                        const entry = list[index];
                        if (entry == null) return null;
                        return (
                          <View key={`s${s}`}>
                            {segment(
                              entry.value,
                              colorFor(s, entry, index),
                              dimmed,
                              groupRowHeight,
                              s * (groupRowHeight + groupRowGap),
                            )}
                          </View>
                        );
                      })
                    : stacked
                      ? (() => {
                          /*
                           * Only the outermost segment is rounded, exactly as the
                           * vertical path rounds the top of a stack and squares
                           * every segment under it. Rounding each segment would
                           * put a notch at every join.
                           *
                           * It has to be explicit rather than left to the rail's
                           * clip: the clip only rounds a fill that actually
                           * reaches the rail's edge, so the one category whose
                           * total set the ceiling came out rounded and every
                           * other row ended square — which reads as a bug in
                           * every row but the biggest.
                           */
                          const filled = allSeries
                            .map((list, s) => ({ s, value: Math.max(0, list[index]?.value ?? 0) }))
                            .filter((entry) => entry.value > 0);
                          const outermost = filled.length - 1;
                          return filled.map((entry, position) => {
                            const from = stackedFrom;
                            stackedFrom += entry.value;
                            const left = span === 0 ? 0 : (from - floor) / span;
                            const size = span === 0 ? 0 : entry.value / span;
                            const color = seriesColorAt(t, entry.s);
                            const end = position === outermost ? ROW_RADIUS : 0;
                            return (
                              <View
                                key={`s${entry.s}`}
                                style={{
                                  position: 'absolute',
                                  left: `${left * 100}%`,
                                  width: `${size * 100}%`,
                                  top: 0,
                                  height: row.height,
                                  borderTopRightRadius: end,
                                  borderBottomRightRadius: end,
                                  backgroundColor:
                                    dimmed && color.startsWith('#')
                                      ? rgbaFromHex(color, DIMMED_ALPHA)
                                      : color,
                                  opacity: dimmed && !color.startsWith('#') ? DIMMED_ALPHA : 1,
                                }}
                              />
                            );
                          });
                        })()
                      : segment(
                          datum.value,
                          colorFor(0, datum, index),
                          dimmed,
                          row.height,
                        )}
                </View>
                <Text
                  numberOfLines={1}
                  style={{
                    width: row.value,
                    textAlign: 'right',
                    color: t.colors.textPrimary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: row.font,
                    lineHeight: row.font + 3,
                    fontWeight: '700',
                    opacity: valueShown ? 1 : 0,
                  }}
                >
                  {formatValue(rowValue)}
                </Text>
              </Pressable>
            );
          },
        )}

        {/*
          The rule runs down the whole rows block rather than once per row — a
          ranked list is read down the column, so the line has to be continuous to
          be comparable against every row at once. Same dash and same hue as the
          vertical path's `ReferenceLine`; only the axis differs.
        */}
        {/*
          Both rules as one SVG overlay, drawn with `strokeDasharray`.

          They were `View`s with `borderStyle: 'dashed'` on a single side, at
          `width: 1` — where the border is the entire view. React Native's
          one-sided dashed borders do not render reliably, so the line was
          invisible and the only sign that `reference` had done anything was the
          chip. A stroked path dashes the same way on every platform, and it is
          what the vertical `ReferenceLine` already uses.
        */}
        {!loading && size.height > 0 && trackWidth > 0 ? (
          <Svg
            width={size.width}
            height={size.height}
            pointerEvents="none"
            style={{ position: 'absolute', top: 0, left: 0 }}
          >
            {showZeroRule ? (
              <Path
                d={ruleAt(zeroAt)}
                stroke={t.colors.borderSecondary}
                strokeWidth={1}
                fill="none"
              />
            ) : null}
            {referenceAt != null ? (
              <Path
                d={ruleAt(referenceAt)}
                stroke={t.colors.focusRingMain}
                strokeWidth={1}
                strokeDasharray="4 4"
                fill="none"
              />
            ) : null}
          </Svg>
        ) : null}

        {/*
          The chip sits on the line it names, not under the chart. Below the rows
          it read as a caption for the whole thing rather than a marker for one
          position — which is the entire job of a reference.
        */}
        {referenceAt != null && !loading && trackWidth > 0 ? (
          <View
            pointerEvents="none"
            style={{
              position: 'absolute',
              top: 0,
              left: railLeft + Math.min(Math.max(referenceAt, 0), 1) * trackWidth,
              transform: [{ translateX: '-50%' }],
              backgroundColor: t.colors.feedbackInfoBg,
              borderRadius: 6,
              paddingHorizontal: 8,
              paddingVertical: 2,
            }}
          >
            <Text
              style={{
                color: t.colors.textInteractiveTertiary,
                fontFamily: t.fontFamilies.sans,
                fontSize: 10,
                lineHeight: 14,
                fontWeight: '700',
              }}
            >
              {reference?.label ?? formatValue(reference?.value ?? 0)}
            </Text>
          </View>
        ) : null}
      </View>

      {legendItems ? <ChartLegend items={legendItems} /> : null}
    </View>
  );
}

/**
 * Arlo UI — DonutChart
 *
 * Part-to-whole: what a total is made of. Use it when the parts sum to something
 * meaningful and there are only a few of them — past a handful, a bar chart ranks
 * better than a ring compares.
 *
 *   <Chart.Donut data={[{ label: 'Rent', value: 1200 }, { label: 'Food', value: 480 }]} />
 *
 * Deliberate choices:
 *
 * - **Four categories, then "Other".** The categorical palette has exactly four
 *   validated slots (see the `chartSeries*` tokens); every slice is on screen at
 *   once here, so they were checked on all pairs, not just neighbours. Anything
 *   past the fourth is summed into a neutral "Other" rather than given an
 *   invented fifth hue.
 * - **The legend is not optional.** Two or more series means identity can never be
 *   colour alone, so each slice is listed with its label and value.
 * - **The hole is cut, not painted.** Each slice is a real annulus — outer arc
 *   out, inner arc back, closed — so the middle is transparent. The old
 *   implementation covered a full pie with an opaque disc, which only reads as a
 *   ring when the disc happens to match what is behind the chart; that is why
 *   this component used to need a `centerColor`, and why it broke on a gradient,
 *   a photo, or glass. There is nothing to match now, so the prop is gone.
 * - **A real gap between slices**, cut out of the arc rather than stroked over it,
 *   so touching arcs stay separable on any background for the same reason.
 * - **Center label, not slice labels.** Text inside thin arcs is unreadable; the
 *   middle holds the total.
 * - **The legend carries selection.** Arcs are poor tap targets, and the legend
 *   has to be on screen anyway.
 */
import { useMemo } from 'react';
import {
  Animated,
  Pressable,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { rgbaFromHex } from '@arloui/tokens';
import { haptic } from '../../foundation/haptics';
import { useTokens } from '../../foundation/theme-provider';
import {
  annulusPath,
  densityMetrics,
  seriesColorAt,
  type ChartDensity,
  type ChartPoint,
} from './core';
import { useControllableIndex, useSkeletonPulse } from './hooks';
import { EmptyContent, type ChartEmptyProps } from './empty';
import { SkeletonBlock } from './skeleton';

export type DonutSlice = ChartPoint & {
  label: string;
  color?: string;
};

export type DonutChartProps = {
  /**
   * Slices of a whole. Non-positive values are dropped, not clamped: a negative
   * share of a total is not a thing a ring can express, and a zero slice has no
   * arc to draw. Anything past `maxSlices` folds into one neutral "Other".
   */
  data: readonly DonutSlice[];
  size?: number;
  /** Ring thickness. Defaults from `density` — 26 at default, 18 at compact. */
  thickness?: number;
  density?: ChartDensity;
  /** Big text in the middle. Defaults to the summed total. */
  /**
   * Hide the figure in the hole, for a ring that is read from its legend or
   * captioned elsewhere. Named to match `Meter`'s `showValue`.
   *
   * Independent of `centerLabel`, which only ever renders when you pass one — so
   * a caption with no number is `showValue={false}` plus a `centerLabel`.
   */
  showValue?: boolean;
  centerValue?: string;
  centerLabel?: string;
  /** Emphasised slice. Controlled when passed; `defaultActiveIndex` seeds the internal one. */
  activeIndex?: number | null;
  defaultActiveIndex?: number | null;
  onSelect?: (index: number, slice: DonutSlice) => void;
  format?: (value: number) => string;
  showLegend?: boolean;
  /**
   * How many arcs the ring draws, **"Other" included**. Categories past that
   * fold into one neutral "Other" slice.
   *
   * Five is the ceiling and the default: the categorical palette has four
   * validated slots, and the fifth arc is "Other". More than four categories
   * always folds, whatever you pass.
   */
  maxSlices?: number;
  /**
   * Short text for the ring's centre when there is no data. Not the whole empty
   * state — see `empty` for the composed one.
   */
  emptyLabel?: string;
  /**
   * The composed empty slot — headline, one line, one action — the same one
   * `Chart.Empty` and `Chart.Bar` draw. Replaces the ring rather than sitting
   * inside it: the arrangement does not fit in a 128pt hole, and a donut with
   * nothing in it has no shape worth preserving.
   *
   * Wins over `emptyLabel`.
   */
  empty?: ChartEmptyProps;
  /**
   * Draws the ring as a pulsing track and holds back the centre readout and the
   * legend. Same footprint as the loaded chart, so nothing reflows when the data
   * lands.
   */
  loading?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

/** Unselected slices fade to this, so the selected one reads as the subject. */
/**
 * The categorical palette's validated slots, and the most arcs a ring may draw:
 * those four plus one "Other".
 */
const NAMED_SLOTS = 4;
const MAX_ARCS = NAMED_SLOTS + 1;

const DIMMED_ALPHA = 0.35;

export function DonutChart({
  data,
  size = 180,
  /*
   * Density picks the default thickness; an explicit `thickness` still wins.
   *
   * It used to move only `metrics.gap`, which is the hairline between slices —
   * 1pt against 2pt, about half a degree at this radius. That is not a control,
   * it is a rounding difference. "How much mark there is" has to change the mark.
   */
  thickness,
  density = 'default',
  showValue = true,
  centerValue,
  centerLabel,
  activeIndex,
  defaultActiveIndex = null,
  onSelect,
  format,
  showLegend = true,
  maxSlices = MAX_ARCS,
  emptyLabel = 'No data',
  empty,
  loading = false,
  accessibilityLabel,
  style,
}: DonutChartProps) {
  const t = useTokens();
  const metrics = densityMetrics(density);
  const ringThickness = thickness ?? (density === 'compact' ? 18 : 26);
  const [selection, setSelection] = useControllableIndex(activeIndex, defaultActiveIndex);

  // Fold everything past the palette's validated capacity into one neutral slice
  // rather than inventing hues that would read as new identities.
  /**
   * `maxSlices` counts the arcs you end up with, "Other" included.
   *
   * It used to cap the *named* categories and then add "Other" on top, so
   * `maxSlices={2}` over four categories drew three arcs. "Other" is a slice —
   * a prop called `maxSlices` that returns more slices than you asked for is
   * simply wrong, whatever the intent behind it was.
   *
   * The palette is what sets the ceiling: four validated slots plus "Other", so
   * five arcs is the most a ring can show and more than four categories always
   * folds, however high `maxSlices` goes.
   */
  const slices = useMemo(() => {
    const positive = data.filter((slice) => slice.value > 0);
    const limit = Math.max(1, Math.min(maxSlices, MAX_ARCS));
    // Fits as-is only if it is inside both the requested limit and the palette.
    if (positive.length <= limit && positive.length <= NAMED_SLOTS) return [...positive];

    // One arc is given up to "Other", and never more than the palette can name.
    const named = Math.min(limit - 1, NAMED_SLOTS);
    const kept = positive.slice(0, named);
    const rest = positive.slice(named).reduce((sum, slice) => sum + slice.value, 0);
    return rest > 0
      ? [...kept, { label: 'Other', value: rest, color: t.colors.chartOther } as DonutSlice]
      : kept;
  }, [data, maxSlices, t.colors.chartOther]);

  const total = slices.reduce((sum, slice) => sum + slice.value, 0);

  const outerRadius = size / 2;
  const innerRadius = Math.max(0, outerRadius - ringThickness);

  const segments = useMemo(() => {
    if (total <= 0) return [];
    const TAU = Math.PI * 2;
    // The gap is taken out of each slice's own sweep, so the ring stays a ring and
    // the space between arcs is genuinely empty rather than painted over.
    const gapAngle = slices.length > 1 ? metrics.gap / outerRadius : 0;
    let cursor = 0;
    return slices.map((slice, index) => {
      const sweep = (slice.value / total) * TAU;
      const start = cursor + gapAngle / 2;
      const end = cursor + sweep - gapAngle / 2;
      cursor += sweep;
      return {
        slice,
        index,
        color: slice.color ?? seriesColorAt(t, index),
        percent: (slice.value / total) * 100,
        startAngle: start,
        endAngle: Math.max(start, end),
      };
    });
  }, [slices, total, metrics.gap, outerRadius, t]);

  const summary =
    accessibilityLabel ??
    (loading
      ? 'Chart loading'
      : segments.length === 0
      ? emptyLabel
      : `Donut chart. ${slices
          .map(
            (slice) =>
              `${slice.label} ${total > 0 ? Math.round((slice.value / total) * 100) : 0} percent`,
          )
          .join(', ')}`);

  const resolvedCenterValue = centerValue ?? (format ? format(total) : String(total));

  /*
   * A composed empty slot replaces the ring outright.
   *
   * The arrangement — tile, headline, a line, an action — does not fit in the
   * hole, and an empty donut has no shape worth preserving around it. This is
   * the same call the bar chart makes: when there is nothing to draw, the slot
   * *is* the chart.
   */
  if (empty && !loading && segments.length === 0) {
    return (
      <View
        style={[{ minHeight: size, alignSelf: 'center', justifyContent: 'center' }, style]}
      >
        <EmptyContent {...empty} />
      </View>
    );
  }

  return (
    <View style={[{ gap: t.spacing[4] }, style]}>
      <View
        accessible
        accessibilityRole="image"
        accessibilityLabel={summary}
        style={{
          width: size,
          height: size,
          alignSelf: 'center',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        {loading ? (
          <DonutSkeleton size={size} outerRadius={outerRadius} innerRadius={innerRadius} />
        ) : null}

        <Svg
          width={size}
          height={size}
          style={{ position: 'absolute' }}
          pointerEvents="none"
        >
          {segments.length > 0 && !loading ? (
            segments.map((segment) => {
              const dimmed = selection != null && selection !== segment.index;
              return (
                <Path
                  key={`${segment.slice.label}-${segment.index}`}
                  d={annulusPath({
                    cx: outerRadius,
                    cy: outerRadius,
                    outerRadius,
                    innerRadius,
                    startAngle: segment.startAngle,
                    endAngle: segment.endAngle,
                  })}
                  // Dimming goes in the colour so it never fades the hole back in.
                  fill={
                    dimmed && segment.color.startsWith('#')
                      ? rgbaFromHex(segment.color, DIMMED_ALPHA)
                      : segment.color
                  }
                  opacity={dimmed && !segment.color.startsWith('#') ? DIMMED_ALPHA : 1}
                />
              );
            })
          ) : loading ? null : (
            // An empty ring is still a ring — the track shows where the data goes.
            <Path
              d={annulusPath({
                cx: outerRadius,
                cy: outerRadius,
                outerRadius,
                innerRadius,
                startAngle: 0,
                endAngle: Math.PI * 2,
              })}
              fill={t.colors.surfaceInput}
            />
          )}
        </Svg>

        <View style={{ alignItems: 'center', paddingHorizontal: ringThickness }}>
          {!showValue ? null : loading ? (
            // A block where the number goes, not a hole. Same rule the plot's
            // readouts follow: the centre value is a figure the chart does not
            // have yet, so it must not be painted — but the space it will take
            // should still read as "a number is coming".
            <SkeletonBlock width={72} height={20} radius={6} />
          ) : (
            <Text
              numberOfLines={1}
              style={{
                color: t.colors.textPrimary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.title2.fontSize,
                lineHeight: t.typography.title2.lineHeight,
                fontWeight: '700',
              }}
            >
              {segments.length === 0 ? emptyLabel : resolvedCenterValue}
            </Text>
          )}
          {centerLabel && segments.length > 0 && !loading ? (
            <Text
              numberOfLines={1}
              style={{
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {centerLabel}
            </Text>
          ) : null}
        </View>
      </View>

      {showLegend && segments.length > 0 && !loading ? (
        <View style={{ gap: t.spacing[2] }}>
          {segments.map((segment) => {
            const selected = selection === segment.index;
            return (
              <Pressable
                key={`legend-${segment.slice.label}-${segment.index}`}
                accessibilityRole="button"
                accessibilityLabel={`${segment.slice.label}, ${
                  format ? format(segment.slice.value) : segment.slice.value
                }, ${segment.percent.toFixed(0)} percent`}
                accessibilityState={{ selected }}
                onPress={() => {
                  void haptic('selection');
                  setSelection(selected ? null : segment.index);
                  onSelect?.(segment.index, segment.slice);
                }}
                style={{ flexDirection: 'row', alignItems: 'center', gap: t.spacing[2] }}
              >
                <View
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: 3,
                    backgroundColor: segment.color,
                  }}
                />
                <Text
                  numberOfLines={1}
                  style={{
                    flex: 1,
                    // Text stays in ink; the swatch beside it carries identity.
                    color: t.colors.textPrimary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                    fontWeight: selected ? '700' : '600',
                  }}
                >
                  {segment.slice.label}
                </Text>
                <Text
                  style={{
                    color: t.colors.textPrimary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                    fontWeight: '700',
                  }}
                >
                  {format ? format(segment.slice.value) : segment.slice.value}
                </Text>
                {/* The share gets its own fixed column so the values line up down
                    the legend — a ranked list you can compare at a glance. */}
                <Text
                  style={{
                    width: 40,
                    textAlign: 'right',
                    color: t.colors.textTertiary,
                    fontFamily: t.fontFamilies.sans,
                    fontSize: t.typography.bodySm.fontSize,
                    lineHeight: t.typography.bodySm.lineHeight,
                  }}
                >
                  {`${Math.round(segment.percent)}%`}
                </Text>
              </Pressable>
            );
          })}
        </View>
      ) : null}
    </View>
  );
}

/**
 * The pulsing track drawn while `loading`.
 *
 * The same annulus the data will fill, at the same radius — a donut that loads as
 * a spinner and then becomes a ring changes size twice on the way in. Nothing is
 * drawn in the centre: the total is the one number a reader would try hardest to
 * believe, so it stays absent rather than being faked with a grey bar.
 */
function DonutSkeleton({
  size,
  outerRadius,
  innerRadius,
}: {
  size: number;
  outerRadius: number;
  innerRadius: number;
}) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  return (
    <Animated.View
      pointerEvents="none"
      style={{ position: 'absolute', width: size, height: size, opacity: pulse }}
    >
      <Svg width={size} height={size}>
        <Path
          d={annulusPath({
            cx: outerRadius,
            cy: outerRadius,
            outerRadius,
            innerRadius,
            startAngle: 0,
            endAngle: Math.PI * 2,
          })}
          // `surfaceStrong`, the skeleton material the plot, the readouts, and
          // the bars use. `surfaceInput` is a token lighter in light mode and
          // near-invisible against the surface in dark.
          fill={t.colors.surfaceStrong}
        />
      </Svg>
    </Animated.View>
  );
}

/**
 * Arlo UI — Meter
 *
 * One value against a target: budget used, storage filled, goal progress. This is
 * a magnitude, not a category, so it is a single hue rather than a series colour —
 * and a `bar`, a `ring`, or an `arc`, which are the same data with different
 * shapes.
 *
 *   <Meter value={72} max={100} label="Storage" />
 *   <Meter shape="ring" value={1840} max={2000} label="Steps" tone="positive" />
 *   <Meter shape="arc" value={712} max={850} label="Credit score" />
 *
 * `arc` is the gauge: the same sweep as the ring with the bottom third left
 * open. It is the shape a score wants — a credit rating, a sleep score, a
 * readiness number — because the gap gives the value somewhere to sit and reads
 * as a dial rather than as progress towards a full circle.
 *
 * `rings` puts more than one value on the same dial, drawn concentrically:
 *
 *   <Meter value={520} max={600} rings={[{ value: 32, max: 40 }]} />
 *
 * That is the one arrangement composition cannot reach. Three meters side by
 * side are three readings; three rings on one dial are a single one.
 *
 * Passing `warnAt` / `dangerAt` moves it onto the status palette, which is
 * reserved for state and always ships with a visible value — never colour alone.
 *
 * The fill sweeps up from empty on mount and on every value change, and the
 * readout counts with it, so the number and the shape always agree mid-flight.
 * It runs on the `slow` duration rather than `base`: a meter is read as a
 * quantity, and a fill that lands before the eye reaches it may as well be
 * static. Reduce Motion pins both straight to the final value.
 */
import { useEffect, useMemo, useState } from 'react';
import {
  Animated,
  Easing,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';
import {
  arcLength,
  arcPath,
  seriesColorAt,
  type ChartDensity,
  type ChartTone,
} from './core';
import { useSkeletonPulse } from './hooks';
import { useReduceMotion } from '../../foundation/reduce-motion';

/**
 * Created once at module scope. Building it inside render returns a new component
 * type every pass, which remounts the circle and drops the animation mid-flight.
 */
const AnimatedCircle = Animated.createAnimatedComponent(Circle);
const AnimatedPath = Animated.createAnimatedComponent(Path);

export type MeterShape = 'bar' | 'ring' | 'arc';

/**
 * The gauge's sweep: 240 degrees, centred on twelve o'clock, leaving the bottom
 * third open. That gap is what makes an arc read as a gauge rather than as a
 * ring someone forgot to close — and it is where the readout's descenders go.
 */
const ARC_SWEEP = (Math.PI * 4) / 3;
const ARC_START = -ARC_SWEEP / 2;
const ARC_END = ARC_SWEEP / 2;

/** Gap between concentric rings, in points. */
const RING_GAP = 4;

/**
 * What `density` means for a meter.
 *
 * It used to mean one thing only: `metrics.showLabels`, which hid the label.
 * That is not density, and it is already what *not passing a label* does — so
 * the axis meant to say "this meter is going somewhere small" changed nothing
 * about its size, and duplicated a decision the caller had already made.
 *
 * It now sizes the meter: the bar's thickness, the ring's stroke and diameter,
 * and the type in the middle. The label is governed by whether you pass one.
 */
const METER_METRICS = {
  default: { bar: 8, ring: 10, size: 120, readoutHole: 64 },
  compact: { bar: 6, ring: 7, size: 88, readoutHole: 48 },
} as const;


/**
 * One more value on the same dial.
 *
 * Concentric rings are the one thing composition genuinely cannot produce: three
 * `Meter`s side by side are three meters, and three rings on one dial are a
 * single reading of a day. Everything a ring needs to differ on is here;
 * everything else it inherits from the meter it sits inside.
 */
export type MeterRing = {
  value: number;
  /** Defaults to the meter's own `max`. */
  max?: number;
  /** Defaults to the meter's own `min`. */
  min?: number;
  /** Overrides the palette slot this ring would otherwise take. */
  color?: string;
  /** Named for assistive tech. Rings have no room for a visible label. */
  label?: string;
};

export type MeterProps = {
  value: number;
  max?: number;
  min?: number;
  shape?: MeterShape;
  /**
   * Honours `brand` (default), `positive`, `negative`, and `neutral`. A meter is
   * one value against a target — it has no series to enumerate and no direction to
   * infer — so `series` and `auto` both resolve to `brand`.
   */
  tone?: ChartTone;
  density?: ChartDensity;
  label?: string;
  /** Text in the middle of a ring, or beside a bar. Defaults to a percentage. */
  valueLabel?: string;
  /**
   * Force the numeric readout on or off. Left unset, a ring or an arc decides
   * from its own geometry: concentric `rings` eat into the hole, and once there
   * is not enough of it left the readout would be drawn over the innermost
   * track. A bar has no hole, so it always shows one.
   *
   * Set it explicitly only where you want to override that — the value stated
   * nearby (`false`), or a crowded dial you have sized yourself (`true`).
   */
  showValue?: boolean;
  /** Fraction (0-1) past which the meter turns warning. */
  warnAt?: number;
  /** Fraction (0-1) past which the meter turns danger. */
  dangerAt?: number;
  /** Bar thickness, or ring stroke width. */
  thickness?: number;
  /** Ring or arc diameter. Ignored by the bar shape. */
  size?: number;
  /**
   * Additional concentric rings, drawn inside the primary one. `value` is always
   * the outermost; these stack inwards in order, exactly as `series` extends
   * `data` on a bar chart.
   *
   * Honoured by `ring` and `arc` only — a bar has no inside to draw into. Extra
   * rings take the categorical palette rather than the meter's `tone`: once there
   * is more than one value on the dial they are categories, and a shared tone
   * would make them unreadable. Thresholds stay with the primary, which is the
   * one the readout reports.
   */
  rings?: readonly MeterRing[];
  /**
   * Pulses the track and holds back the fill and the readout. The label stays —
   * it is the one part of a meter you already know before the value arrives, and
   * skeletoning known text just makes the row flicker.
   *
   * There is no `emptyLabel` counterpart: a meter is one value against a target,
   * so it is either loading or it has a value. An empty meter is a zero.
   */
  loading?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

/**
 * One track and one fill at a given radius, for a full ring or a partial arc.
 *
 * Both shapes animate the same way — `strokeDasharray` over the path's own
 * length — so they share a component rather than diverging into two nearly
 * identical branches. A full turn keeps the `<Circle>` it has always used; only
 * the partial sweep needs a path, because an arc is not a circle.
 */
function Sweep({
  cx,
  cy,
  radius,
  thickness,
  color,
  trackColor,
  trackOpacity,
  progress,
  partial,
}: {
  cx: number;
  cy: number;
  radius: number;
  thickness: number;
  color: string;
  trackColor: string;
  trackOpacity: Animated.Value | number;
  progress: Animated.Value;
  /** `false` draws the full circle; `true` draws the gauge's 240-degree arc. */
  partial: boolean;
}) {
  const length = partial ? arcLength(radius, ARC_SWEEP) : 2 * Math.PI * radius;
  const offset = progress.interpolate({ inputRange: [0, 1], outputRange: [length, 0] });

  if (partial) {
    const d = arcPath({ cx, cy, radius, startAngle: ARC_START, endAngle: ARC_END });
    return (
      <>
        <Path
          d={d}
          stroke={trackColor}
          strokeWidth={thickness}
          strokeLinecap="round"
          fill="none"
          opacity={trackOpacity as number}
        />
        <AnimatedPath
          d={d}
          stroke={color}
          strokeWidth={thickness}
          strokeLinecap="round"
          fill="none"
          strokeDasharray={length}
          strokeDashoffset={offset}
        />
      </>
    );
  }

  return (
    <>
      <AnimatedCircle
        cx={cx}
        cy={cy}
        r={radius}
        stroke={trackColor}
        strokeWidth={thickness}
        fill="none"
        opacity={trackOpacity}
      />
      <AnimatedCircle
        cx={cx}
        cy={cy}
        r={radius}
        stroke={color}
        strokeWidth={thickness}
        strokeLinecap="round"
        fill="none"
        strokeDasharray={length}
        strokeDashoffset={offset}
        // Start the sweep at 12 o'clock instead of 3.
        transform={`rotate(-90 ${cx} ${cy})`}
      />
    </>
  );
}

/**
 * An inner ring, which owns its own sweep.
 *
 * A component per ring rather than a loop of hooks in the parent: the number of
 * rings is a prop, and `useState`/`useEffect` cannot be called a variable number
 * of times. Each ring animating itself also means adding one never restarts the
 * others.
 */
function ExtraRing({
  ring,
  index,
  cx,
  cy,
  radius,
  thickness,
  trackColor,
  trackOpacity,
  fallbackMin,
  fallbackMax,
  partial,
  loading,
  reduceMotion,
  duration,
}: {
  ring: MeterRing;
  index: number;
  cx: number;
  cy: number;
  radius: number;
  thickness: number;
  trackColor: string;
  trackOpacity: Animated.Value | number;
  fallbackMin: number;
  fallbackMax: number;
  partial: boolean;
  loading: boolean;
  reduceMotion: boolean;
  duration: number;
}) {
  const t = useTokens();
  const [progress] = useState(() => new Animated.Value(0));
  const min = ring.min ?? fallbackMin;
  const max = ring.max ?? fallbackMax;
  const range = max - min;
  const fraction =
    loading || range === 0 ? 0 : Math.min(1, Math.max(0, (ring.value - min) / range));

  useEffect(() => {
    if (reduceMotion) {
      progress.setValue(fraction);
      return;
    }
    progress.setValue(0);
    const animation = Animated.timing(progress, {
      toValue: fraction,
      duration,
      easing: Easing.out(Easing.cubic),
      // Stroke offset is not a transform, so this cannot go native.
      useNativeDriver: false,
    });
    animation.start();
    return () => animation.stop();
  }, [fraction, progress, reduceMotion, duration, partial]);

  return (
    <Sweep
      cx={cx}
      cy={cy}
      radius={radius}
      thickness={thickness}
      // +1 because the primary already holds the first slot.
      color={ring.color ?? seriesColorAt(t, index + 1)}
      trackColor={trackColor}
      trackOpacity={trackOpacity}
      progress={progress}
      partial={partial}
    />
  );
}

export function Meter({
  value,
  max = 100,
  min = 0,
  shape = 'bar',
  tone = 'brand',
  density = 'default',
  label,
  valueLabel,
  showValue,
  warnAt,
  dangerAt,
  thickness,
  size,
  rings,
  loading = false,
  accessibilityLabel,
  style,
}: MeterProps) {
  const t = useTokens();
  const scale = METER_METRICS[density === 'compact' ? 'compact' : 'default'];
  const meterThickness = thickness ?? (shape === 'bar' ? scale.bar : scale.ring);
  const meterSize = size ?? scale.size;
  /** A smaller dial takes a smaller figure — 20pt in an 88pt ring reads oversized. */
  const readoutType = density === 'compact' ? t.typography.title3 : t.typography.title2;
  const reduceMotion = useReduceMotion();
  const [progress] = useState(() => new Animated.Value(0));

  const range = max - min;
  // The fill stays empty while loading — a meter that sweeps to a real number
  // before the number is known has already told the reader something false.
  const fraction =
    loading || range === 0 ? 0 : Math.min(1, Math.max(0, (value - min) / range));
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  const trackOpacity = loading ? pulse : 1;

  /**
   * What the readout currently says. Tracks `progress` while the fill sweeps, so
   * it starts at empty alongside it — seeding this with `fraction` would paint
   * the final number for one frame before the sweep yanked it back to zero.
   */
  const [shownFraction, setShownFraction] = useState(0);


  useEffect(() => {
    if (reduceMotion) {
      // No listener and no state write — the readout reads `fraction` directly
      // in this mode, so there is nothing to keep in sync.
      progress.setValue(fraction);
      return;
    }
    // The readout is driven off the same value as the fill, so the number and the
    // shape can never disagree part-way through the sweep.
    const id = progress.addListener(({ value }) => setShownFraction(value));
    // Every presentation begins empty, including when the consumer switches
    // between bar and ring. The listener above resets the painted readout too.
    progress.setValue(0);
    const animation = Animated.timing(progress, {
      toValue: fraction,
      duration: t.motion.duration.slow,
      easing: Easing.out(Easing.cubic),
      // Width and stroke offset are layout properties, so this can't go native.
      useNativeDriver: false,
    });
    animation.start(({ finished }) => {
      // Land exactly on the target: the last listener frame is close, not equal.
      if (finished) setShownFraction(fraction);
    });
    return () => {
      animation.stop();
      progress.removeListener(id);
    };
  }, [fraction, progress, reduceMotion, shape, t.motion.duration.slow]);

  // Thresholds move the meter onto the reserved status palette; without them it
  // stays on the requested tone.
  const color = useMemo(() => {
    if (dangerAt != null && fraction >= dangerAt) return t.colors.feedbackError;
    if (warnAt != null && fraction >= warnAt) return t.colors.feedbackWarning;
    // `auto` and `series` land on brand: there is no direction to infer from one
    // value, and no categories to enumerate.
    return tone === 'positive'
      ? t.colors.chartPositive
      : tone === 'negative'
        ? t.colors.chartNegative
        : tone === 'neutral'
          ? t.colors.textSecondary
          : t.colors.interactivePrimary;
  }, [dangerAt, warnAt, fraction, tone, t.colors]);

  /**
   * The settled value. Assistive tech gets this one — a screen reader announcing
   * a number that is still counting reads as noise, and the meter's semantic
   * value is where it is going, not where the sweep currently is.
   */
  const readout = valueLabel ?? `${Math.round(fraction * 100)}%`;
  /** What is painted, which counts up with the fill — or lands flat under Reduce Motion. */
  const shownReadout =
    valueLabel ?? `${Math.round((reduceMotion ? fraction : shownFraction) * 100)}%`;
  const a11y = accessibilityLabel ?? (loading ? 'Loading' : label);

  /**
   * `compact` drops the caption, which is the inline case: a bare bar sitting next
   * to text that already names it. The value readout is governed by `showValue`
   * and is left alone — a meter with neither a label nor a number is a decoration.
   */
  /*
   * `label != null` alone. Density used to hide it, which is the same decision
   * as not passing one — so the two controls fought over a single outcome and
   * neither was legible. Density sizes the meter; the label is yours.
   */
  const withLabel = label != null;

  const track = t.colors.surfaceInput;
  /** A bar has no hole for the readout to crowd, so it shows one unless told not to. */
  const barReadout = showValue ?? true;

  if (shape === 'ring' || shape === 'arc') {
    const partial = shape === 'arc';
    const cx = meterSize / 2;
    const cy = meterSize / 2;
    const outerRadius = (meterSize - meterThickness) / 2;
    const extras = rings ?? [];

    /*
     * Whether the hole can still hold a readout.
     *
     * Each concentric ring takes a track and a gap out of the middle, so at the
     * default 120/10 a second extra ring leaves 44pt of clear space — and the
     * readout is a ~45x40 box, a 20pt figure with its caption under it. It was
     * drawn anyway, straight over the innermost track.
     *
     * Measured rather than counted, so it stays right for any `size` and
     * `thickness` a caller picks instead of only for the default.
     */
    const innermost = outerRadius - extras.length * (meterThickness + RING_GAP);
    const hole = 2 * (innermost - meterThickness / 2);
    const readoutFits = hole >= scale.readoutHole;
    const withReadout = showValue ?? readoutFits;

    /*
     * An arc only occupies the top two thirds of its box, so the box is cropped
     * to what it draws. The lowest ink is the cap at ±120 degrees, which sits at
     * `cy + radius/2`; anything below that is empty and would read as the gauge
     * floating high in its own space.
     */
    const boxHeight = partial
      ? Math.ceil(cy + outerRadius / 2 + meterThickness / 2)
      : meterSize;

    return (
      <View
        accessible
        accessibilityRole="progressbar"
        accessibilityLabel={a11y}
        accessibilityValue={{ min, max, now: value, text: readout }}
        style={[
          { width: meterSize, height: boxHeight, alignItems: 'center', justifyContent: 'center' },
          style,
        ]}
      >
        <Svg width={meterSize} height={meterSize} style={{ position: 'absolute', top: 0, left: 0 }}>
          <Sweep
            cx={cx}
            cy={cy}
            radius={outerRadius}
            thickness={meterThickness}
            color={color}
            trackColor={track}
            trackOpacity={trackOpacity}
            progress={progress}
            partial={partial}
          />
          {extras.map((ring, index) => (
            <ExtraRing
              key={ring.label ?? index}
              ring={ring}
              index={index}
              cx={cx}
              cy={cy}
              radius={outerRadius - (index + 1) * (meterThickness + RING_GAP)}
              thickness={meterThickness}
              trackColor={track}
              trackOpacity={trackOpacity}
              fallbackMin={min}
              fallbackMax={max}
              partial={partial}
              loading={loading}
              reduceMotion={reduceMotion}
              duration={t.motion.duration.slow}
            />
          ))}
        </Svg>
        {withReadout ? (
          <View
            style={[
              { alignItems: 'center' },
              partial
                ? {
                    /*
                     * Centred *on* the dial's centre, not hung from it. This was
                     * `top: cy`, which puts the readout's top edge at the middle
                     * and drops the whole box through the arc's lower legs —
                     * their lowest ink sits at `cy + outerRadius / 2`, right
                     * where the text was landing.
                     */
                    position: 'absolute',
                    top: cy,
                    left: 0,
                    right: 0,
                    transform: [{ translateY: '-50%' }],
                  }
                : null,
            ]}
          >
            {/*
              The cap lives on an inner wrapper, not the box above it.

              Never wider than the hole can hold: a box centred in a circle only
              clears it if its diagonal does, so the safe width is the inscribed
              square's side. It cannot go on the positioning box because the arc
              anchors that with `left: 0; right: 0` — a `maxWidth` there makes the
              box that wide *from the left edge* instead of centring it.
            */}
            <View style={{ alignItems: 'center', maxWidth: Math.max(24, hole * 0.7) }}>
            {!loading ? (
              <Text
                // One line, always. A long `valueLabel` used to wrap and grow the
                // box downwards into the track — the same clash as running wide,
                // on the other axis.
                numberOfLines={1}
                style={{
                  color: t.colors.textPrimary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: readoutType.fontSize,
                  lineHeight: readoutType.lineHeight,
                  fontWeight: '700',
                }}
              >
                {shownReadout}
              </Text>
            ) : null}
            {withLabel ? (
              <Text
                numberOfLines={1}
                style={{
                  color: t.colors.textSecondary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: t.typography.bodySm.fontSize,
                  lineHeight: t.typography.bodySm.lineHeight,
                }}
              >
                {label}
              </Text>
            ) : null}
            </View>
          </View>
        ) : null}
      </View>
    );
  }

  return (
    <View
      accessible
      accessibilityRole="progressbar"
      accessibilityLabel={a11y}
      accessibilityValue={{ min, max, now: value, text: readout }}
      style={[
        {
          gap: t.spacing[1],
          /*
           * A bar has no intrinsic width — its track fills whatever it is given.
           * Inside a parent with `alignItems: 'center'` that means it collapses
           * to the width of the label row above it and the line reads as a stub.
           * `alignSelf` beats the parent's `alignItems`, so the bar stays full
           * width wherever it is dropped; `style` still comes after and wins.
           */
          alignSelf: 'stretch',
        },
        style,
      ]}
    >
      {withLabel || barReadout ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
          {withLabel ? (
            <Text
              numberOfLines={1}
              style={{
                flexShrink: 1,
                color: t.colors.textSecondary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
              }}
            >
              {label}
            </Text>
          ) : (
            <View />
          )}
          {barReadout && !loading ? (
            <Text
              style={{
                color: t.colors.textPrimary,
                fontFamily: t.fontFamilies.sans,
                fontSize: t.typography.bodySm.fontSize,
                lineHeight: t.typography.bodySm.lineHeight,
                fontWeight: '600',
              }}
            >
              {shownReadout}
            </Text>
          ) : null}
        </View>
      ) : null}
      <Animated.View
        style={{
          height: meterThickness,
          borderRadius: t.radii.full,
          backgroundColor: track,
          overflow: 'hidden',
          opacity: trackOpacity,
        }}
      >
        <Animated.View
          style={{
            height: '100%',
            borderRadius: t.radii.full,
            backgroundColor: color,
            width: progress.interpolate({
              inputRange: [0, 1],
              outputRange: ['0%', '100%'],
            }),
          }}
        />
      </Animated.View>
    </View>
  );
}

/**
 * Arlo UI — Heatmap
 *
 * A calendar of filled and empty squares: streaks, consistency, "show up" grids.
 * The mark is so simple it needs no charting library and no axes — a square is
 * either a day with something in it or a day without, and the ramp only ever
 * says *how much*, never *which kind*, of activity.
 *
 *   <Chart.Heatmap data={[{ date: '2026-03-01', value: 2 }]} onSelect={...} />
 *
 * The headline streak count is the app's to compose — the grid is the component,
 * the number is the story, and the two do not have to load together.
 *
 * Deliberate choices:
 *
 * - **Monday-first columns, one week per row.** A month grid is read as "week
 *   across, weekday down"; the M T W T F S S header pins the columns so an
 *   unlabelled ramp of squares never has to be decoded.
 * - **The ramp is one hue, in tints of the brand.** Intensity is a magnitude, so
 *   it does not spend the categorical palette — and tints of `interactivePrimary`
 *   survive both modes because they are derived from it, not chosen beside it.
 * - **Empty days are the input track, not white.** The grid has to read on any
 *   surface, and a hard-coded empty square is a white square in dark mode.
 * - **Days with no datum are empty, not absent.** `from`/`to` pad the grid to
 *   whole weeks so the columns line up; a gap in the data is information.
 * - **Selection is per day, and only when asked.** Without an `onSelect` the grid
 *   is one image to a screen reader — forty-two tappable squares is not a
 *   control surface, it is noise.
 */
import { useMemo } from 'react';
import { Animated, Pressable, Text, View, type StyleProp, type ViewStyle } from 'react-native';
import { rgbaFromHex } from '@arloui/tokens';
import { haptic } from '../../foundation/haptics';
import { useTokens } from '../../foundation/theme-provider';
import type { ChartPoint } from './core';
import { useSkeletonPulse } from './hooks';

export type HeatmapDatum = ChartPoint & {
  /** A timestamp, an ISO string, or a `Date` — normalised to local midnight. */
  date: string | number | Date;
};

export type HeatmapProps = {
  /** Dated values. A day with no entry renders empty, not absent. */
  data: readonly HeatmapDatum[];
  /** Filled intensity steps above "none". Default 3. */
  levels?: number;
  /** Grid start; defaults to the earliest datum, wound back to Monday. */
  from?: string | number | Date;
  /** Grid end; defaults to the latest datum, run on to Sunday. */
  to?: string | number | Date;
  /** Weekday initials over the columns. On by default. */
  showDayLabels?: boolean;
  /** The Less–More scale under the grid. On by default. */
  showScale?: boolean;
  /** Tapping a day. Without this the grid is one image, not forty-two buttons. */
  onSelect?: (datum: HeatmapDatum | null, date: Date) => void;
  /** Formats a day's value in its accessibility label. */
  format?: (value: number) => string;
  /** Pulses the empty grid instead of the data. */
  loading?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

const DAY_INITIALS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

/** Local midnight of a day, as the number every lookup keys on. */
function dayKey(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
}

function toDate(value: string | number | Date): Date {
  return value instanceof Date ? value : new Date(value);
}

/** The Monday at or before `date`, local midnight. */
function startOfWeek(date: Date): Date {
  const day = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const offset = (day.getDay() + 6) % 7; // Sunday -> 6, Monday -> 0.
  day.setDate(day.getDate() - offset);
  return day;
}

/** The Sunday at or after `date`, local midnight. */
function endOfWeek(date: Date): Date {
  const day = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const offset = 7 - ((day.getDay() + 6) % 7) - 1;
  day.setDate(day.getDate() + offset);
  return day;
}

export function Heatmap({
  data,
  levels = 3,
  from,
  to,
  showDayLabels = true,
  showScale = true,
  onSelect,
  format,
  loading = false,
  accessibilityLabel,
  style,
}: HeatmapProps) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  const interactive = onSelect != null;

  const byDay = useMemo(() => {
    const map = new Map<number, HeatmapDatum>();
    for (const datum of data) map.set(dayKey(toDate(datum.date)), datum);
    return map;
  }, [data]);

  const { weeks, maxValue } = useMemo(() => {
    let maxValue = 0;
    for (const datum of data) if (datum.value > maxValue) maxValue = datum.value;

    const first = data[0]?.date;
    const last = data[data.length - 1]?.date;
    /*
     * No data and no explicit range: there is no month to draw, and inventing
     * "this week" would dress nothing up as somewhere. The grid stays empty and
     * the summary says so.
     */
    const start = from != null ? startOfWeek(toDate(from)) : first != null ? startOfWeek(toDate(first)) : null;
    let end = to != null ? endOfWeek(toDate(to)) : last != null ? endOfWeek(toDate(last)) : null;
    if (start == null || end == null) return { weeks: [], maxValue };
    if (end.getTime() < start.getTime()) end = start;

    const days: { key: number; date: Date }[] = [];
    const cursor = new Date(start);
    while (cursor.getTime() <= end.getTime()) {
      days.push({ key: dayKey(cursor), date: new Date(cursor) });
      cursor.setDate(cursor.getDate() + 1);
    }
    // One week per row: the grid is read as "week across, weekday down".
    const weeks: { key: number; date: Date }[][] = [];
    for (let index = 0; index < days.length; index += 7) {
      weeks.push(days.slice(index, index + 7));
    }
    return { weeks, maxValue };
  }, [data, from, to]);

  /**
   * Level 0 is "none"; 1..levels bucket the value's share of the busiest day.
   * Bucketing against the series max keeps the ramp relative — a grid of small
   * numbers still shows which days carried the week.
   */
  const levelFor = (value: number): number => {
    if (value <= 0 || maxValue <= 0) return 0;
    return Math.min(levels, Math.max(1, Math.ceil((value / maxValue) * levels)));
  };

  const levelColor = (level: number): string => {
    if (level <= 0) return t.colors.surfaceInput;
    const base = t.colors.interactivePrimary;
    if (!base.startsWith('#')) return base;
    const alpha = levels === 1 ? 1 : 0.25 + (0.75 * (level - 1)) / (levels - 1);
    return rgbaFromHex(base, alpha);
  };

  const activeDays = useMemo(
    () => weeks.flat().filter(({ key }) => (byDay.get(key)?.value ?? 0) > 0).length,
    [weeks, byDay],
  );

  const summary =
    accessibilityLabel ??
    (loading
      ? 'Heatmap loading'
      : weeks.length === 0
        ? 'No data'
        : `Heatmap, ${activeDays} of ${weeks.length * 7} days with activity`);

  const cellLabel = (datum: HeatmapDatum, date: Date) => {
    const when = date.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short' });
    const value = format ? format(datum.value) : String(datum.value);
    return `${when}, ${value}`;
  };

  return (
    <View style={[{ gap: t.spacing[2] }, style]}>
      {/* `Animated.View`, not `View`: the pulse is an Animated.Value, and a plain
          view would hand the native side an object where it expects a number. */}
      <Animated.View
        accessible={!interactive}
        accessibilityRole={interactive ? undefined : 'image'}
        accessibilityLabel={interactive ? undefined : summary}
        style={{ gap: 5, opacity: loading ? pulse : 1 }}
      >
        {showDayLabels ? (
          <View style={{ flexDirection: 'row', gap: 5 }}>
            {DAY_INITIALS.map((initial, index) => (
              <Text
                key={`${initial}-${index}`}
                style={{
                  flex: 1,
                  textAlign: 'center',
                  color: t.colors.textTertiary,
                  fontFamily: t.fontFamilies.sans,
                  fontSize: 10,
                  lineHeight: 12,
                  fontWeight: '600',
                }}
              >
                {initial}
              </Text>
            ))}
          </View>
        ) : null}

        {weeks.map((week, weekIndex) => (
          <View key={`week-${weekIndex}`} style={{ flexDirection: 'row', gap: 5 }}>
            {week.map((cell) => {
              const datum = loading ? null : (byDay.get(cell.key) ?? null);
              const level = datum ? levelFor(datum.value) : 0;
              const backgroundColor = loading ? t.colors.surfaceInput : levelColor(level);
              const square = {
                flex: 1,
                aspectRatio: 1,
                borderRadius: 3,
                backgroundColor,
              } as const;

              if (!interactive || loading || !datum) {
                return <View key={cell.key} style={square} />;
              }

              return (
                <Pressable
                  key={cell.key}
                  accessibilityRole="button"
                  accessibilityLabel={cellLabel(datum, cell.date)}
                  onPress={() => {
                    void haptic('selection');
                    onSelect(datum, cell.date);
                  }}
                  style={square}
                />
              );
            })}
          </View>
        ))}
      </Animated.View>

      {showScale && !loading ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
          <Text
            style={{
              color: t.colors.textTertiary,
              fontFamily: t.fontFamilies.sans,
              fontSize: 11,
              lineHeight: 14,
            }}
          >
            Less
          </Text>
          {Array.from({ length: levels + 1 }, (_, level) => (
            <View key={level} style={{ width: 11, height: 11, borderRadius: 3, backgroundColor: levelColor(level) }} />
          ))}
          <Text
            style={{
              color: t.colors.textTertiary,
              fontFamily: t.fontFamilies.sans,
              fontSize: 11,
              lineHeight: 14,
            }}
          >
            More
          </Text>
        </View>
      ) : null}
    </View>
  );
}

/**
 * Arlo UI — Chart.Legend
 *
 * The identity row every multi-series form shares: `Chart.Bar` with two series,
 * `Chart.Plot` with a `compare` line or a `range` band. Swatch and label, laid
 * out in the order the series are drawn, because a legend that reads in a
 * different order than the marks is worse than none.
 *
 * It exists as a standalone export because the compare plot composes its own
 * chrome — the legend can't live inside the plot there — while `Chart.Bar`
 * mounts the same component when given `legend` labels. One legend, so both
 * forms read the same.
 *
 * Identity is never colour alone: the label is the identity, the swatch is the
 * pointer. That is also why there is no icon-only or swatch-only mode.
 */
import { Text, View, type StyleProp, type ViewStyle } from 'react-native';
import { useTokens } from '../../foundation/theme-provider';

export type ChartLegendItem = {
  label: string;
  color: string;
  /** Lowers the swatch to match a band drawn at reduced opacity. */
  faded?: boolean;
};

export type ChartLegendProps = {
  items: readonly ChartLegendItem[];
  style?: StyleProp<ViewStyle>;
};

export function ChartLegend({ items, style }: ChartLegendProps) {
  const t = useTokens();
  if (items.length === 0) return null;

  return (
    <View
      accessibilityRole="text"
      style={[{ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: t.spacing[4] }, style]}
    >
      {items.map((item) => (
        <View key={item.label} style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
          <View
            style={{
              width: 10,
              height: 10,
              borderRadius: 3,
              backgroundColor: item.color,
              opacity: item.faded ? 0.18 : 1,
            }}
          />
          <Text
            numberOfLines={1}
            style={{
              color: t.colors.textSecondary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.bodySm.fontSize,
              lineHeight: t.typography.bodySm.lineHeight,
              fontWeight: '600',
            }}
          >
            {item.label}
          </Text>
        </View>
      ))}
    </View>
  );
}

/**
 * Arlo UI — the empty slot every chart form shares.
 *
 * Failing to a blank rectangle is how a data screen looks broken, so "no data"
 * is a composed thing: a headline, one line, and one action. It lives here
 * rather than inside `Chart` because a bar chart with nothing in it is exactly
 * as empty as a plot with nothing in it, and the two should not say so
 * differently — a `Chart.Plot` offering "Log a transaction" beside a
 * `Chart.Bar` offering a grey "No data" is one screen speaking with two voices.
 */
import { type ReactNode } from 'react';
import { Platform, Pressable, Text, View } from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';
import { useTokens } from '../../foundation/theme-provider';

export type ChartEmptyProps = {
  /** The headline. One short statement of what is not here yet. */
  title?: string;
  /** One line on why, or on what will fill it. Kept to a single sentence. */
  description?: string;
  /** The one thing to do about it. Omit where there is nothing the reader can do. */
  action?: { label: string; onPress: () => void };
  /** Replaces the default glyph in the tile. */
  icon?: ReactNode;
  /** Drops the tile entirely, for a slot that is mostly words. */
  showIcon?: boolean;
  /** A fully custom slot. Wins over every prop above. */
  children?: ReactNode;
};

/** The default glyph: a series that has not happened yet. */
export function EmptyGlyph({ color }: { color: string }) {
  return (
    <Svg width={26} height={26} viewBox="0 0 26 26">
      <Path
        d="M2,17 L8,11 L13,14 L21,5"
        fill="none"
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <Circle cx={21} cy={5} r={2} fill={color} />
    </Svg>
  );
}

/**
 * The rendered empty slot. Lives here rather than in `ChartEmpty` because the
 * plot draws it inside its own box — `ChartEmpty` only carries the configuration.
 */
export function EmptyContent({ title, description, action, icon, showIcon = true }: ChartEmptyProps) {
  const t = useTokens();
  return (
    <View style={{ alignItems: 'center', justifyContent: 'center', paddingHorizontal: t.spacing[4], gap: t.spacing[3] }}>
      {showIcon ? (
        <View
          style={{
            width: 52,
            height: 52,
            borderRadius: 14,
            backgroundColor: t.colors.surfaceRaised,
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          {icon ?? <EmptyGlyph color={t.colors.borderStrong} />}
        </View>
      ) : null}
      {title ? (
        <Text
          style={{
            color: t.colors.textPrimary,
            fontFamily: t.fontFamilies.sans,
            fontSize: t.typography.title3.fontSize,
            lineHeight: t.typography.title3.lineHeight,
            fontWeight: '700',
            textAlign: 'center',
          }}
        >
          {title}
        </Text>
      ) : null}
      {description ? (
        <Text
          style={{
            color: t.colors.textSecondary,
            fontFamily: t.fontFamilies.sans,
            fontSize: t.typography.bodySm.fontSize,
            lineHeight: t.typography.bodySm.lineHeight * 1.15,
            textAlign: 'center',
            // A measure, not a width: centred text past ~40 characters a line
            // stops being scannable.
            maxWidth: 260,
          }}
        >
          {description}
        </Text>
      ) : null}
      {action ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={action.label}
          onPress={action.onPress}
          hitSlop={8}
          style={({ pressed }) => ({
            marginTop: 2,
            opacity: pressed ? t.motion.pressed.opacity : 1,
            cursor: Platform.OS === 'web' ? 'pointer' : undefined,
          })}
        >
          <Text
            style={{
              color: t.colors.interactivePrimary,
              fontFamily: t.fontFamilies.sans,
              fontSize: t.typography.bodySm.fontSize,
              lineHeight: t.typography.bodySm.lineHeight,
              fontWeight: '600',
            }}
          >
            {action.label} →
          </Text>
        </Pressable>
      ) : null}
    </View>
  );
}

/**
 * Arlo UI — the skeleton block every chart readout stands behind.
 *
 * Shared rather than per-form so that "loading" is one material across the
 * system: the plot's value and delta, the period pills, and the donut's centre
 * all pulse the same grey. It lives in its own file because `chart.tsx` already
 * imports the other forms — a form importing back would close a cycle.
 */
import { Animated } from 'react-native';
import { useTokens } from '../../foundation/theme-provider';
import { useSkeletonPulse } from './hooks';

/**
 * A skeleton block in the shape of the thing it stands in for.
 *
 * The readouts do not render a placeholder number while loading. A chart that
 * paints `$0.00` before it has a figure has told the reader something false, and
 * it is indistinguishable from a real zero balance — the one value a money
 * screen must never invent. A block says "not yet"; a zero says "nothing".
 */
export function SkeletonBlock({
  width,
  height,
  radius,
}: {
  /** A number, or a percentage for a block that fills its slot. */
  width: number | `${number}%`;
  height: number;
  radius: number;
}) {
  const t = useTokens();
  const pulse = useSkeletonPulse(t.motion.duration.slow);
  return (
    <Animated.View
      style={{
        width,
        height,
        borderRadius: radius,
        backgroundColor: t.colors.surfaceStrong,
        opacity: pulse,
      }}
    />
  );
}
